const db={users:[],clinics:[],appointments:[],pharmacies:[],payments:[],notifications:[],reviews:[],reports:[],logs:[],invoices:[],emergencies:[],mobileVisits:[],messages:[],admin:{}};
let lang='ar',current=null,screen='home',adminTab='dashboard',registerType='patient',selectedClinic=null,searchFilter='',bookingDate='',bookingTime='',paymentMethod='card';
let remoteHydrated=false;
function save(){ if(remoteHydrated && typeof window.sihatiPersistState==='function') window.sihatiPersistState(); }
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function uid(p){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function toast(s){const e=document.getElementById('toast');e.textContent=s;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2400)}
function log(action,details=''){db.logs.unshift({id:uid('l'),action,details,date:new Date().toISOString(),admin:db.admin.email});db.logs=db.logs.slice(0,200)}
function isActive(c){return c.status==='active'&&c.subscription?.active&&c.subscription.expires&&new Date(c.subscription.expires+'T23:59:59')>=new Date()}
function clinics(){return db.clinics.filter(isActive)}
function showScreen(s){screen=s;render();window.scrollTo({top:0,behavior:'smooth'})}
function toggleLanguage(){lang=lang==='ar'?'fr':lang==='fr'?'en':'ar';render()}
function openDrawer(){document.getElementById('drawer').classList.remove('hidden');renderDrawer()}
function closeDrawer(){document.getElementById('drawer').classList.add('hidden')}
function handleDrawerAuth(){if(current)logout();else openAuth('login');closeDrawer()}
function renderDrawer(){const u=document.getElementById('drawerUser');const b=document.getElementById('drawerAuthBtn');if(current){u.innerHTML=`<b>${esc(current.name)}</b><small>${current.type==='clinic'?'🏥 حساب عيادة':'👤 حساب مريض'}</small>`;b.textContent='↪ تسجيل الخروج'}else{u.innerHTML=`<b>مرحبا بك في SIHATI</b><small>دخل لحسابك أو أنشئ حساب جديد</small><div style="display:grid;gap:7px;margin-top:10px"><button class="btn btn-primary" onclick="openAuth('login');closeDrawer()">🔐 تسجيل الدخول</button><button class="btn btn-soft" onclick="openAuth('register');closeDrawer()">📝 إنشاء حساب</button></div>`;b.textContent='🔐 تسجيل الدخول'}}

