I18N.fr=FR;I18N.en=EN;
function applyTranslations(){
 const map=I18N[lang]||I18N.ar;
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 nodes.forEach(n=>{const raw=n.nodeValue, t=raw.trim(); if(map[t]) n.nodeValue=raw.replace(t,map[t]);});
 document.querySelectorAll('input[placeholder],textarea[placeholder],input[aria-label],button[title]').forEach(el=>{const attrs=['placeholder','aria-label','title'];attrs.forEach(a=>{if(el.getAttribute(a)&&map[el.getAttribute(a)])el.setAttribute(a,map[el.getAttribute(a)]);});});
}


function clinicStatus(c){
  if(!c) return {key:'closed',text:'مغلقة',cls:'closed'};
  if(!isActive(c)) return {key:'inactive',text:'غير مفعلة',cls:'inactive'};
  if(isOpenNow(c)) return {key:'open',text:'مفتوحة الآن',cls:'open'};
  const d=new Date(),map=['sun','mon','tue','wed','thu','fri','sat'],x=c.schedule?.[map[d.getDay()]];
  if(x?.enabled && x.from){const now=d.toTimeString().slice(0,5); if(now<x.from)return {key:'soon',text:'ستفتح قريباً',cls:'soon'};}
  return {key:'closed',text:'مغلقة الآن',cls:'closed'};
}
function ensureClinicData(c){
  if(!c)return;
  c.verified= c.verified!==false;
  c.doctors=Array.isArray(c.doctors)&&c.doctors.length?c.doctors:[{id:uid('d'),name:c.doctor||'الطبيب المسؤول',specialty:c.specialty||'تخصص طبي',experience:'غير محدد',languages:'العربية',bio:c.description||''}];
  c.services=Array.isArray(c.services)?c.services:[]; c.mobileVisit=!!c.mobileVisit; c.mobileVisitPrice=c.mobileVisitPrice||'';
}
function doctorCard(d){return `<div class="doctor-card"><div class="doctor-avatar">👨‍⚕️</div><div class="doctor-info"><b>${esc(d.name||'—')}</b><span>${esc(d.specialty||'—')}</span><small>${d.experience?`🧠 ${esc(d.experience)} خبرة`:''}${d.languages?` · 🌐 ${esc(d.languages)}`:''}</small></div><button class="btn btn-soft" onclick="openDoctorProfile('${selectedClinic?.id||''}','${d.id}')">عرض الملف</button></div>`}
function openDoctorProfile(clinicId,doctorId){const c=db.clinics.find(x=>x.id===clinicId);const d=c?.doctors?.find(x=>x.id===doctorId);if(!d)return;openModal(`<div class="doctor-profile"><div class="doctor-avatar big">👨‍⚕️</div><span class="eyebrow">${esc(d.specialty||c.specialty||'')}</span><h2>${esc(d.name)}</h2><p>${esc(d.bio||'لا توجد نبذة متاحة حالياً.')}</p><div class="notice"><b>الخبرة:</b> ${esc(d.experience||'غير محددة')}<br><b>اللغات:</b> ${esc(d.languages||'غير محددة')}</div><button class="btn btn-primary" style="width:100%;margin-top:12px" onclick="closeModal();startBooking('${c.id}')">🗓️ حجز موعد</button></div>`)}
function buildMapEmbed(c){const lat=c?.location?.lat,lng=c?.location?.lng;if(lat&&lng)return `<iframe class="clinic-map" loading="lazy" src="https://www.google.com/maps?q=${encodeURIComponent(lat+','+lng)}&output=embed" title="موقع العيادة"></iframe>`;return `<div class="map-box">📍 ${esc(c?.address||'الموقع غير محدد')}</div>`}
function searchScore(c,q){const text=[c.name,c.doctor,c.specialty,c.address,c.description,...(c.doctors||[]).map(d=>`${d.name} ${d.specialty}`)].join(' ').toLowerCase();if(!q)return 0;let score=0;for(const term of q.split(/\s+/).filter(Boolean)){if(text.includes(term))score+=term.length>3?2:1}if(c.verified)score+=1;if(isOpenNow(c))score+=1;return score}
function enhancedSearch(){
 const input=document.getElementById('searchInput');const q=(input?.value||'').trim().toLowerCase();let arr=clinics().filter(c=>{const text=[c.name,c.doctor,c.specialty,c.address,c.description,...(c.doctors||[]).map(d=>`${d.name} ${d.specialty}`)].join(' ').toLowerCase();return !q||q.split(/\s+/).every(t=>text.includes(t))});
 const open=document.getElementById('filterOpen')?.checked;if(open)arr=arr.filter(isOpenNow);
 const verified=document.getElementById('filterVerified')?.checked;if(verified)arr=arr.filter(c=>c.verified);
 const sort=document.getElementById('searchSort')?.value||'relevance';
 if(sort==='rating')arr.sort((a,b)=>(b.rating||0)-(a.rating||0));
 else if(sort==='name')arr.sort((a,b)=>a.name.localeCompare(b.name));
 else arr.sort((a,b)=>searchScore(b,q)-searchScore(a,q));
 const box=document.getElementById('searchResults');if(box)box.innerHTML=arr.map(clinicCard).join('')||emptyCard('ما لقيناش نتائج مطابقة');
}
function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.getElementById('langBtn').textContent=lang==='ar'?'FR':lang==='fr'?'EN':'AR';document.querySelectorAll('[data-t]').forEach(e=>e.textContent=T[lang][e.dataset.t]||e.textContent);document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.screen===screen));document.getElementById('notifDot').style.display=db.notifications.some(n=>!n.read&&(n.userId===current?.id||!n.userId))?'block':'none';document.getElementById('screenRoot').innerHTML=(screens[screen]||screens.home)();if(screen==='home')renderHomeData();if(screen==='search')renderSearch();if(screen==='appointments')renderAppointments();if(screen==='notifications')renderNotifications();if(screen==='profile')renderProfile();if(screen==='pharmacies')renderPharmacies();if(screen==='favorites')renderFavorites();if(screen==='clinicDashboard')renderClinicDashboard();if(screen==='admin')renderAdmin();renderDrawer();applyTranslations()}
const screens={
home:()=>`<div class="screen"><section class="hero"><span class="eyebrow">SIHATI • العيون</span><h1>الصحة ديالك،<br>أقرب ليك.</h1><p>اكتشف العيادات الموثقة، الأطباء، أوقات العمل وحجز موعدك من الهاتف.</p><div class="search-box"><span>⌕</span><input id="homeSearch" placeholder="عيادة، طبيب أو تخصص..." oninput="quickSearch(this.value)"><button onclick="showScreen('search')">بحث</button></div>${!current?`<div class="hero-actions"><button class="btn" style="background:white;color:#087f6b" onclick="openAuth('login')">🔐 تسجيل الدخول</button><button class="btn" style="background:#ffffff1c;color:white;border:1px solid #ffffff40" onclick="openAuth('register')">📝 إنشاء حساب</button></div>`:''}<div class="stats"><div class="stat"><b id="statClinics">0</b><span>عيادات</span></div><div class="stat"><b id="statSpecs">0</b><span>تخصصات</span></div><div class="stat"><b>24/7</b><span>معلومات</span></div></div>${!current?`<div style="margin-top:10px;font-size:11px;opacity:.82">🏥 عندك عيادة؟ <button style="background:none;color:white;text-decoration:underline;font-weight:800" onclick="openAuth('register');setTimeout(()=>setRegisterType('clinic'),60)">إنشاء حساب العيادة</button></div>`:''}</section><section class="quick-services"><button class="emergency-card" onclick="openEmergency()"><span class="quick-icon">🚨</span><div><b>حالة مستعجلة</b><small>طبيب أو ممرض يجي عندك في الحال</small></div><span class="quick-arrow">←</span></button><button class="mobile-card" onclick="openMobileDoctorRequest()"><span class="quick-icon">🏠</span><div><b>طبيب متنقل</b><small>رعاية طبية في منزلك بدون تنقل</small></div><span class="quick-arrow">←</span></button></section><section class="section"><div class="section-head"><div><span class="eyebrow">استكشف</span><h2>التخصصات</h2></div></div><div id="homeChips" class="chips"></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">مختارة لك</span><h2>العيادات الموثقة</h2></div><button class="btn btn-soft" onclick="showScreen('search')">الكل</button></div><div id="homeClinics" class="clinic-grid"></div></section><section class="section"><div class="pharmacy-card"><span class="eyebrow">حراسة اليوم</span><h2>صيدليات الحراسة</h2><p>شوف الصيدليات المكلفة بالحراسة اليوم.</p><button class="btn" style="background:white;color:#087f6b" onclick="showScreen('pharmacies')">عرض الصيدليات</button></div></section></div>`,
search:()=>`<div class="screen"><div class="section-head"><div><span class="eyebrow">دليل SIHATI</span><h2>البحث عن عيادة</h2></div><button class="btn btn-soft" onclick="requestLocation()">📍 قريب مني</button></div><div class="form-card"><div class="search-box" style="border:1px solid #dce8e5"><span>⌕</span><input id="searchInput" placeholder="عيادة، طبيب، تخصص، حي..." oninput="enhancedSearch()"></div><div class="chips" style="margin-top:10px"><button class="chip active" onclick="setFilter('')">الكل</button>${specialties.map(s=>`<button class="chip" onclick="setFilter('${esc(s)}')">${esc(s)}</button>`).join('')}</div><div class="search-filters"><label class="checkbox-line"><input id="filterOpen" type="checkbox" onchange="enhancedSearch()"> 🕐 مفتوحة الآن</label><label class="checkbox-line"><input id="filterVerified" type="checkbox" onchange="enhancedSearch()"> ✓ موثقة فقط</label><select id="searchSort" onchange="enhancedSearch()"><option value="relevance">الأكثر صلة</option><option value="rating">الأعلى تقييماً</option><option value="name">حسب الاسم</option></select></div></div><div class="section"><div id="searchResults" class="clinic-grid"></div></div></div>`,
appointments:()=>`<div class="screen"><div class="section-head"><div><span class="eyebrow">حسابك</span><h2>المواعيد</h2></div></div><div id="appointmentsBox"></div></div>`,emergency:()=>`<div class="screen"><div class="service-hero emergency-hero"><span>🚨</span><div><span class="eyebrow">خدمة عاجلة</span><h2>حالة مستعجلة</h2><p>اطلب طبيباً أو ممرضاً ليصل إليك بأسرع وقت.</p></div></div><div class="form-card emergency-form"><div class="alert-note">⚠️ هذه الخدمة للحالات التي تحتاج تدخلاً سريعاً. في حالة الخطر الشديد اتصل بخدمات الطوارئ المحلية.</div><form class="form" onsubmit="submitEmergency(event)"><label>نوع المساعدة<select id="emType"><option>طبيب</option><option>ممرض / ممرضة</option></select></label><label>الحالة أو الأعراض<textarea id="emSymptoms" required placeholder="مثلاً: ألم شديد، دوخة، جرح..."></textarea></label><label>رقم الهاتف<input id="emPhone" inputmode="tel" required placeholder="06XXXXXXXX"></label><label>الموقع / العنوان<textarea id="emAddress" required placeholder="أدخل عنوانك بدقة"></textarea></label><button class="btn btn-emergency">🚨 إرسال طلب عاجل</button></form></div><div id="emergencyStatus"></div></div>`,
mobileDoctor:()=>`<div class="screen"><div class="service-hero mobile-hero"><span>🏠</span><div><span class="eyebrow">رعاية منزلية</span><h2>طبيب متنقل</h2><p>اختار طبيباً يقدم الزيارة المنزلية، واطلب منه الحضور إلى بيتك.</p></div></div><div class="form-card"><form class="form" onsubmit="submitMobileVisit(event)"><label>التخصص المطلوب<select id="mvSpec">${specialties.map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label>الخدمة المطلوبة<select id="mvType"><option>زيارة طبيب منزلية</option><option>زيارة ممرض / ممرضة</option><option>متابعة منزلية</option><option>حقن / تغيير ضماد</option></select></label><label>الهاتف<input id="mvPhone" inputmode="tel" required></label><label>العنوان<textarea id="mvAddress" required placeholder="الحي، الشارع، رقم المنزل..."></textarea></label><label>ملاحظات<textarea id="mvNote" placeholder="أعراض أو معلومات إضافية"></textarea></label><button class="btn btn-primary">🏠 طلب زيارة منزلية</button></form></div><div class="section"><div class="notice"><b>كيف تعمل؟</b><br>أرسل الطلب → نبحث عن مقدم خدمة متاح → تتوصل بتأكيد الطلب والموعد.</div></div></div>`, 
notifications:()=>`<div class="screen"><div class="section-head"><div><span class="eyebrow">تنبيهات SIHATI</span><h2>الإشعارات</h2></div><button class="btn btn-soft" onclick="markAllRead()">تحديد الكل كمقروء</button></div><div id="notificationsBox"></div></div>`,
profile:()=>`<div class="screen"><div id="profileBox"></div></div>`,
favorites:()=>`<div class="screen"><div class="section-head"><div><span class="eyebrow">حسابك</span><h2>العيادات المفضلة ❤️</h2></div></div><div id="favoritesBox" class="favorite-grid"></div></div>`,
pharmacies:()=>`<div class="screen"><div class="section-head"><div><span class="eyebrow">حراسة اليوم</span><h2>الصيدليات المكلفة بالحراسة</h2></div></div><div id="pharmaciesBox"></div></div>`,
clinicDashboard:()=>`<div class="screen"><div id="clinicDashBox"></div></div>`,
admin:()=>`<div class="screen"><div id="adminBox"></div></div>`};
function renderHomeData(){document.getElementById('statClinics').textContent=clinics().length;document.getElementById('statSpecs').textContent=new Set(clinics().map(c=>c.specialty)).size;document.getElementById('homeChips').innerHTML=specialties.slice(0,8).map(s=>`<button class="chip" onclick="setFilter('${esc(s)}');showScreen('search')">${esc(s)}</button>`).join('');document.getElementById('homeClinics').innerHTML=clinics().slice(0,6).map(clinicCard).join('')||emptyCard('لا توجد عيادات مفعلة حالياً')}
function quickSearch(v){if(document.getElementById('homeSearch')){if(v.trim()){searchFilter=v;showScreen('search');setTimeout(()=>{document.getElementById('searchInput').value=v;renderSearch()},0)}}}
function setFilter(s){searchFilter=s;showScreen('search')}
function renderSearch(){const input=document.getElementById('searchInput');const q=(input?.value||searchFilter||'').trim().toLowerCase();if(input&&!input.dataset.bound){input.dataset.bound='1';input.addEventListener('input',enhancedSearch)}enhancedSearch();}
function clinicCard(c){ensureClinicData(c);const fav=isFav(c.id);const st=clinicStatus(c);const img=c.images?.[0]||'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" width="800" height="500"><rect width="100%" height="100%" fill="%23dfeae7"/><text x="50%" y="50%" text-anchor="middle" dominant-baseline="middle" fill="%23087f6b" font-size="34">SIHATI</text></svg>';return `<article class="clinic-card"><div class="clinic-cover"><img src="${img}" alt="${esc(c.name)}"><span class="verified ${c.verified?'':'hidden'}">✓ موثقة</span>${c.mobileVisit?'<span class="verified mobile-badge">🏠 متنقل</span>':''}<span class="rating">⭐ ${c.rating||'جديد'}</span><span class="clinic-status-badge ${st.cls}">${st.text}</span><button class="fav-btn" onclick="toggleFavorite('${c.id}')">${fav?'❤️':'♡'}</button></div><div class="clinic-body"><div class="clinic-title"><h3>${esc(c.name)}</h3></div><span class="specialty">${esc(c.specialty)}</span><div class="meta"><span>👨‍⚕️ ${esc(c.doctor||c.doctors?.[0]?.name||'—')}</span><span>📍 ${esc(c.address||'—')}</span><span>🕐 ${st.text}</span></div><div class="actions"><button class="btn btn-outline" onclick="openClinic('${c.id}')">التفاصيل</button><button class="btn btn-primary" onclick="startBooking('${c.id}')">حجز موعد</button></div></div></article>`}
function emptyCard(t){return `<div class="empty"><strong>⌁</strong><div>${esc(t)}</div></div>`}
function openClinic(id){
 selectedClinic=db.clinics.find(c=>c.id===id);if(!selectedClinic)return;ensureClinicData(selectedClinic);
 const imgs=(selectedClinic.images||[]).slice(0,3);const gallery=imgs.length?imgs.map((x,i)=>`<img class="${i?'small':''}" src="${x}" alt="${esc(selectedClinic.name)}">`).join(''):`<div class="map-box">🏥 SIHATI</div>`;
 const services=(selectedClinic.services?.length?selectedClinic.services:[{name:'استشارة طبية',price:'حسب العيادة'}]).map(s=>`<div class="service-row"><span>${esc(s.name)}</span><span>${esc(s.price)} DH</span><span></span></div>`).join('');
 const hours=days.map(([k,n])=>{const x=selectedClinic.schedule?.[k];return `<div class="hours-item ${x?.enabled?'':'closed'}"><b>${n}</b><span>${x?.enabled?esc(x.from)+' — '+esc(x.to):'مغلق'}</span></div>`}).join('');
 const reviews=(selectedClinic.reviews||[]).map(r=>`<div class="review"><b>⭐ ${r.rating}/5</b><br>${esc(r.text)}<small> — ${esc(r.userName||'مستخدم')}</small></div>`).join('')||'<div class="empty">لا توجد تقييمات بعد</div>';
 const doctors=(selectedClinic.doctors||[]).map(doctorCard).join('');const st=clinicStatus(selectedClinic);
 openModal(`<div class="gallery">${gallery}</div><div class="detail-head"><div><span class="eyebrow">${esc(selectedClinic.specialty)}</span><h2>${esc(selectedClinic.name)}</h2><p>👨‍⚕️ ${esc(selectedClinic.doctor||'—')} ${selectedClinic.verified?' · ✓ موثقة':''}</p></div><span class="mini-badge">${st.text} · ⭐ ${selectedClinic.rating||'جديد'}</span></div><div class="detail-actions"><button class="btn btn-primary" onclick="startBooking('${selectedClinic.id}')">🗓️ حجز موعد</button><button class="btn btn-outline" onclick="toggleFavorite('${selectedClinic.id}');closeModal();openClinic('${selectedClinic.id}')">${isFav(selectedClinic.id)?'❤️ مفضلة':'♡ أضف للمفضلة'}</button></div><div class="detail-section"><h3>الأطباء والطاقم</h3><div class="doctor-list">${doctors}</div></div><div class="detail-section"><h3>الخدمات والأسعار</h3>${services}</div><div class="detail-section"><h3>أوقات العمل</h3><div class="clinic-hours">${hours}</div></div><div class="detail-section"><h3>الموقع</h3>${buildMapEmbed(selectedClinic)}<button class="btn btn-soft" style="margin-top:8px" onclick="openMaps('${selectedClinic.location?.lat||''}','${selectedClinic.location?.lng||''}')">🗺️ فتح الخريطة</button></div><div class="detail-section"><h3>تقييمات المرضى</h3>${reviews}</div><div class="detail-actions"><button class="btn btn-soft" onclick="openReview('${selectedClinic.id}')">⭐ تقييم العيادة</button><button class="btn btn-outline" onclick="reportClinic('${selectedClinic.id}')">⚠️ الإبلاغ</button></div>`);
}
function openMaps(lat,lng){if(lat&&lng)window.open(`https://www.google.com/maps?q=${lat},${lng}`,'_blank');else toast('الموقع الجغرافي غير متوفر')}
function isOpenNow(c){const d=new Date(),map=['sun','mon','tue','wed','thu','fri','sat'];const x=c.schedule?.[map[d.getDay()]];if(!x?.enabled)return false;const now=d.toTimeString().slice(0,5);return now>=x.from&&now<=x.to}
function toggleOpenNow(btn){btn.classList.toggle('active');const box=document.getElementById('searchResults');if(btn.classList.contains('active'))box.innerHTML=clinics().filter(isOpenNow).map(clinicCard).join('')||emptyCard('لا توجد عيادات مفتوحة الآن');else renderSearch()}
function sortByRating(){document.getElementById('searchResults').innerHTML=clinics().sort((a,b)=>(b.rating||0)-(a.rating||0)).map(clinicCard).join('')||emptyCard('لا توجد عيادات')}
function isFav(id){return current?.favorites?.includes(id)}
function toggleFavorite(id){if(!current){openAuth('login');return}current.favorites=current.favorites||[];current.favorites=current.favorites.includes(id)?current.favorites.filter(x=>x!==id):[...current.favorites,id];save();toast(current.favorites.includes(id)?'تمت الإضافة للمفضلة ❤️':'تم الحذف من المفضلة');render()}
function renderFavorites(){const box=document.getElementById('favoritesBox');const arr=clinics().filter(c=>isFav(c.id));box.innerHTML=arr.map(clinicCard).join('')||emptyCard('ما عندك حتى عيادة فالمفضلة')}
function startBooking(id){if(!current){closeModal();openAuth('login');toast('خاصك تسجل الدخول أولاً');return}if(current.type!=='patient'){toast('الحجز متاح لحسابات المرضى');return}selectedClinic=db.clinics.find(c=>c.id===id);bookingDate='';bookingTime='';const today=new Date();const dateBtns=Array.from({length:7},(_,i)=>{let d=new Date(today);d.setDate(today.getDate()+i);let v=d.toISOString().slice(0,10);return `<button type="button" class="day-btn" onclick="selectBookingDate('${v}',this)">${d.toLocaleDateString(lang==='ar'?'ar-MA':'fr-FR',{weekday:'short'})}<br>${d.getDate()}/${d.getMonth()+1}</button>`}).join('');openModal(`<h2>🗓️ حجز موعد</h2><p>${esc(selectedClinic.name)}</p><div class="detail-section"><h3>اختار اليوم</h3><div class="calendar-grid">${dateBtns}</div></div><div class="detail-section"><h3>اختار الساعة</h3><div id="slots" class="slot-grid"><div class="empty">اختار اليوم أولاً</div></div></div><form class="form" style="margin-top:14px" onsubmit="confirmBooking(event)"><label>نوع الاستشارة<select id="bType"><option>استشارة</option><option>متابعة</option><option>فحص</option></select></label><label>ملاحظة<textarea id="bNote" placeholder="ملاحظة اختيارية"></textarea></label><button class="btn btn-primary">تأكيد الموعد</button></form>`)}
function selectBookingDate(v,el){bookingDate=v;document.querySelectorAll('.day-btn').forEach(x=>x.classList.remove('active'));el.classList.add('active');let d=new Date(v+'T12:00:00'),map=['sun','mon','tue','wed','thu','fri','sat'],x=selectedClinic.schedule?.[map[d.getDay()]],slots=[];if(x?.enabled){let [h,m]=x.from.split(':').map(Number),[eh,em]=x.to.split(':').map(Number);for(let mins=h*60+m;mins<eh*60+em;mins+=30)slots.push(String(Math.floor(mins/60)).padStart(2,'0')+':'+String(mins%60).padStart(2,'0'))}document.getElementById('slots').innerHTML=slots.map(t=>`<button type="button" class="slot" onclick="selectSlot('${t}',this)">${t}</button>`).join('')||emptyCard('العيادة مغلقة هذا اليوم')}
function selectSlot(t,el){bookingTime=t;document.querySelectorAll('.slot').forEach(x=>x.classList.remove('active'));el.classList.add('active')}
function confirmBooking(e){e.preventDefault();if(!bookingDate||!bookingTime)return toast('اختار اليوم والساعة');const a={id:uid('a'),clinicId:selectedClinic.id,userId:current.id,date:bookingDate,time:bookingTime,type:bType.value,note:bNote.value,status:'pending',createdAt:new Date().toISOString()};db.appointments.push(a);db.notifications.unshift({id:uid('n'),userId:current.id,text:`تم إرسال طلب موعدك مع ${selectedClinic.name} بتاريخ ${bookingDate} على الساعة ${bookingTime}.`,read:false,date:new Date().toISOString()});save();closeModal();toast('تم إرسال طلب الموعد');showScreen('appointments')}
function openEmergency(){if(!current){openAuth('login');toast('سجل الدخول أولاً لطلب خدمة عاجلة');return}showScreen('emergency');}
function submitEmergency(e){e.preventDefault();if(!current)return;const r={id:uid('em'),userId:current.id,type:emType.value,symptoms:emSymptoms.value,phone:emPhone.value,address:emAddress.value,status:'new',createdAt:new Date().toISOString()};db.emergencies=db.emergencies||[];db.emergencies.unshift(r);db.notifications.unshift({id:uid('n'),userId:current.id,text:'تم استلام طلب الحالة المستعجلة وسيتم التعامل معه بأسرع وقت.',read:false,date:new Date().toISOString(),kind:'emergency'});save();document.getElementById('screenRoot').querySelector('.emergency-form').innerHTML='<div class="success-card">✅<h3>تم إرسال الطلب العاجل</h3><p>توصلنا بطلبك. احتفظ بهاتفك مفتوحاً لتلقي الاتصال والتأكيد.</p><button class="btn btn-primary" onclick="showScreen(&quot;home&quot;)">العودة للرئيسية</button></div>';toast('تم إرسال طلب عاجل 🚨')}
function openMobileDoctorRequest(){if(!current){openAuth('login');toast('سجل الدخول أولاً لطلب زيارة منزلية');return}showScreen('mobileDoctor');}
function submitMobileVisit(e){e.preventDefault();if(!current)return;const r={id:uid('mv'),userId:current.id,specialty:mvSpec.value,type:mvType.value,phone:mvPhone.value,address:mvAddress.value,note:mvNote.value,status:'new',createdAt:new Date().toISOString()};db.mobileVisits=db.mobileVisits||[];db.mobileVisits.unshift(r);db.notifications.unshift({id:uid('n'),userId:current.id,text:`تم إرسال طلب زيارة منزلية في تخصص ${r.specialty}.`,read:false,date:new Date().toISOString(),kind:'mobile'});save();toast('تم إرسال طلب الزيارة المنزلية 🏠');showScreen('appointments');}
function renderAppointments(){const box=document.getElementById('appointmentsBox');if(!current)return box.innerHTML=`${emptyCard('خاصك تسجل الدخول باش تشوف المواعيد')}<button class="btn btn-primary" style="margin-top:8px" onclick="openAuth('login')">🔐 تسجيل الدخول</button>`;if(current.type==='clinic')return renderClinicAppointments(box);const arr=db.appointments.filter(a=>a.userId===current.id).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));box.innerHTML=arr.map(a=>{let c=db.clinics.find(x=>x.id===a.clinicId);return `<div class="appointment"><div class="appointment-top"><b>${esc(c?.name||'عيادة')}</b><span class="status ${a.status}">${a.status==='pending'?'في الانتظار':a.status==='confirmed'?'مؤكد':a.status==='completed'?'مكتمل':'ملغى'}</span></div><p>📅 ${a.date} · 🕐 ${a.time}</p><small>${esc(a.type)} ${a.note?'· '+esc(a.note):''}</small>${a.status==='pending'||a.status==='confirmed'?`<button class="danger" style="margin-top:8px" onclick="cancelAppointment('${a.id}')">إلغاء الموعد</button>`:''}${a.status==='completed'?`<button class="btn btn-soft" style="margin-top:8px" onclick="reviewAppointment('${a.id}')">⭐ تقييم العيادة</button>`:''}</div>`}).join('')||emptyCard('ما عندك حتى موعد')}
function renderClinicAppointments(box){const c=db.clinics.find(x=>x.ownerId===current.id);const arr=db.appointments.filter(a=>a.clinicId===c?.id).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));box.innerHTML=arr.map(a=>`<div class="appointment"><div class="appointment-top"><b>👤 ${esc(db.users.find(u=>u.id===a.userId)?.name||'مريض')}</b><span class="status ${a.status}">${a.status}</span></div><p>📅 ${a.date} · 🕐 ${a.time}</p><small>${esc(a.type)} ${a.note?'· '+esc(a.note):''}</small><div class="actions" style="margin-top:8px">${a.status==='pending'?`<button class="success" onclick="setAppointmentStatus('${a.id}','confirmed')">تأكيد</button><button class="danger" onclick="setAppointmentStatus('${a.id}','cancelled')">رفض</button>`:''}${a.status==='confirmed'?`<button class="btn btn-soft" onclick="setAppointmentStatus('${a.id}','completed')">تم الموعد</button><button class="danger" onclick="setAppointmentStatus('${a.id}','cancelled')">إلغاء</button>`:''}</div></div>`).join('')||emptyCard('لا توجد مواعيد')}
function setAppointmentStatus(id,status){let a=db.appointments.find(x=>x.id===id);a.status=status;db.notifications.unshift({id:uid('n'),userId:a.userId,text:`تم تحديث موعدك إلى: ${status==='confirmed'?'مؤكد':status==='completed'?'مكتمل':'ملغى'}.`,read:false,date:new Date().toISOString()});save();renderAppointments();toast('تم تحديث الموعد')}
function cancelAppointment(id){setAppointmentStatus(id,'cancelled')}
function reviewAppointment(id){const a=db.appointments.find(x=>x.id===id),c=db.clinics.find(x=>x.id===a.clinicId);openModal(`<h2>⭐ تقييم العيادة</h2><p>${esc(c.name)}</p><form class="form" onsubmit="submitReview(event,'${id}')"><label>التقييم<select id="revRating"><option value="5">⭐⭐⭐⭐⭐</option><option value="4">⭐⭐⭐⭐</option><option value="3">⭐⭐⭐</option><option value="2">⭐⭐</option><option value="1">⭐</option></select></label><label>تعليق<textarea id="revText" required></textarea></label><button class="btn btn-primary">إرسال التقييم</button></form>`)}
function submitReview(e,id){e.preventDefault();const a=db.appointments.find(x=>x.id===id),c=db.clinics.find(x=>x.id===a.clinicId),r={id:uid('r'),appointmentId:id,clinicId:c.id,userId:current.id,userName:current.name,rating:+revRating.value,text:revText.value,status:'published'};db.reviews.push(r);c.reviews=c.reviews||[];c.reviews.push(r);c.rating=+(c.reviews.reduce((s,x)=>s+x.rating,0)/c.reviews.length).toFixed(1);save();closeModal();toast('شكراً على تقييمك ⭐')}
function renderNotifications(){const box=document.getElementById('notificationsBox');if(!current)return box.innerHTML=`${emptyCard('سجل الدخول لمشاهدة الإشعارات')}<button class="btn btn-primary" onclick="openAuth('login')">تسجيل الدخول</button>`;const arr=db.notifications.filter(n=>n.userId===current.id||!n.userId);box.innerHTML=arr.map(n=>`<div class="notice" style="margin-bottom:8px;opacity:${n.read?.7:1}" onclick="readNotif('${n.id}')"><strong>${n.read?'':'🔔 '}${esc(n.text)}</strong><small>${new Date(n.date).toLocaleString()}</small></div>`).join('')||emptyCard('ما عندك حتى إشعار')}
function readNotif(id){const n=db.notifications.find(x=>x.id===id);if(n)n.read=true;save();renderNotifications();render()}
function markAllRead(){if(current)db.notifications.filter(n=>n.userId===current.id).forEach(n=>n.read=true);save();render()}
function renderProfile(){const box=document.getElementById('profileBox');if(!current)return box.innerHTML=`<section class="hero"><span class="eyebrow">SIHATI</span><h1>حسابك كيسهّل عليك الحجز.</h1><p>دخل لحسابك أو أنشئ حساب جديد باش تحفظ المفضلة والمواعيد والتقييمات.</p><div class="hero-actions"><button class="btn" style="background:white;color:#087f6b" onclick="openAuth('login')">🔐 تسجيل الدخول</button><button class="btn" style="background:#ffffff1c;color:white;border:1px solid #ffffff40" onclick="openAuth('register')">📝 إنشاء حساب</button></div></section>`;if(current.type==='clinic')return renderClinicProfile(box);box.innerHTML=`<div class="section-head"><div><span class="eyebrow">حساب المريض</span><h2>مرحبا ${esc(current.name)} 👋</h2></div></div><div class="profile-grid"><div class="form-card"><b>${esc(current.email)}</b><small style="display:block;color:#71817e">${esc(current.phone||'')}</small></div><button class="profile-action" onclick="showScreen('appointments')">📅 مواعيدي <span>›</span></button><button class="profile-action" onclick="showScreen('favorites')">❤️ المفضلة <span>›</span></button><button class="profile-action" onclick="showScreen('notifications')">🔔 الإشعارات <span>›</span></button><button class="profile-action" onclick="openPasswordChange()">🔐 تغيير كلمة المرور <span>›</span></button><button class="profile-action danger-text" onclick="logout()">🚪 تسجيل الخروج</button></div>`}
function renderClinicProfile(box){const c=db.clinics.find(x=>x.ownerId===current.id);box.innerHTML=`<div class="section-head"><div><span class="eyebrow">حساب العيادة</span><h2>${esc(c?.name||current.name)}</h2></div><span class="mini-badge">${c&&isActive(c)?'نشطة':'غير مفعلة'}</span></div><div class="profile-grid"><button class="profile-action" onclick="showScreen('clinicDashboard')">🏥 لوحة العيادة <span>›</span></button><button class="profile-action" onclick="showScreen('appointments')">📅 المواعيد <span>›</span></button><button class="profile-action" onclick="openClinicEditor('${c?.id}')">✏️ تعديل بيانات العيادة <span>›</span></button><button class="profile-action" onclick="openPayment('${c?.id}')">💳 الاشتراك والدفع <span>›</span></button><button class="profile-action danger-text" onclick="logout()">🚪 تسجيل الخروج</button></div>`}
function renderPharmacies(){const box=document.getElementById('pharmaciesBox');const today=new Date().toISOString().slice(0,10);const arr=db.pharmacies.filter(p=>!p.date||p.date===today||p.always);box.innerHTML=arr.map(p=>`<div class="pharmacy-item"><strong>💊 ${esc(p.name)}</strong><small>📍 ${esc(p.address)}</small><small>🕐 ${esc(p.from||'20:00')} → ${esc(p.to||'08:00')}</small><a href="tel:${esc(p.phone)}">📞 اتصال</a>${p.lat&&p.lng?`<a href="https://www.google.com/maps?q=${p.lat},${p.lng}" target="_blank">📍 الخريطة</a>`:''}</div>`).join('')||emptyCard('لا توجد صيدلية حراسة مضافة لليوم')}
function renderClinicDashboard(){const box=document.getElementById('clinicDashBox');const c=db.clinics.find(x=>x.ownerId===current?.id);if(!current||current.type!=='clinic'||!c)return box.innerHTML=emptyCard('هذه الصفحة خاصة بالعيادات');const pending=db.appointments.filter(a=>a.clinicId===c.id&&a.status==='pending').length;box.innerHTML=`<div class="admin-header"><span class="eyebrow">CLINIC DASHBOARD</span><h2>${esc(c.name)}</h2><p>${c.status==='active'&&isActive(c)?'✅ الحساب نشط':'⚠️ الحساب غير مفعل — خاصك الاشتراك والتفعيل'}</p></div><div class="admin-kpi" style="margin:12px 0"><div class="stat" style="background:white;border:1px solid #e2ebe8"><b>${db.appointments.filter(a=>a.clinicId===c.id).length}</b><span>المواعيد</span></div><div class="stat" style="background:white;border:1px solid #e2ebe8"><b>${pending}</b><span>في الانتظار</span></div></div><div class="admin-nav"><button class="active" onclick="renderClinicDashboard()">الملخص</button><button onclick="openClinicEditor('${c.id}')">البيانات</button><button onclick="openPayment('${c.id}')">💳 الاشتراك</button></div><div class="panel"><h3>أوقات العمل</h3><div class="clinic-hours">${days.map(([k,n])=>{let x=c.schedule?.[k];return `<div class="hours-item ${x?.enabled?'':'closed'}"><b>${n}</b><span>${x?.enabled?x.from+' — '+x.to:'مغلق'}</span></div>`}).join('')}</div><h3 style="margin-top:18px">الأطباء والطاقم</h3><div class="doctor-list">${(c.doctors||[]).map(d=>`<div class="doctor-card"><div class="doctor-avatar">👨‍⚕️</div><div class="doctor-info"><b>${esc(d.name)}</b><span>${esc(d.specialty||'')}</span><small>${esc(d.experience||'')} ${d.languages?'· '+esc(d.languages):''}</small></div><button class="danger" onclick="removeDoctor('${c.id}','${d.id}')">حذف</button></div>`).join('')}</div><button class="btn btn-soft" style="margin-top:8px" onclick="addDoctor('${c.id}')">+ إضافة طبيب</button><h3 style="margin-top:18px">إدارة الخدمات</h3>${(c.services||[]).map((s,i)=>`<div class="service-row"><span>${esc(s.name)}</span><span>${esc(s.price)} DH</span><button class="danger" onclick="removeService('${c.id}',${i})">حذف</button></div>`).join('')}<button class="btn btn-soft" style="margin-top:8px" onclick="addService('${c.id}')">+ إضافة خدمة</button></div>`}
function addDoctor(id){openModal(`<h2>👨‍⚕️ إضافة طبيب</h2><form class="form" onsubmit="saveDoctor(event,'${id}')"><label>اسم الطبيب<input id="dName" required></label><label>التخصص<input id="dSpec" required></label><label>سنوات الخبرة<input id="dExp" placeholder="مثلاً: 8 سنوات"></label><label>اللغات<input id="dLang" placeholder="العربية، الفرنسية"></label><label>نبذة<textarea id="dBio"></textarea></label><button class="btn btn-primary">حفظ الطبيب</button></form>`)}
function saveDoctor(e,id){e.preventDefault();const c=db.clinics.find(x=>x.id===id);c.doctors=c.doctors||[];c.doctors.push({id:uid('d'),name:dName.value,specialty:dSpec.value,experience:dExp.value,languages:dLang.value,bio:dBio.value});save();closeModal();renderClinicDashboard();toast('تمت إضافة الطبيب')}
function removeDoctor(cid,did){const c=db.clinics.find(x=>x.id===cid);if(!c)return;c.doctors=(c.doctors||[]).filter(d=>d.id!==did);save();renderClinicDashboard();toast('تم حذف الطبيب')}
function addService(id){const name=prompt('اسم الخدمة');if(!name)return;const price=prompt('السعر بالدرهم','0');const c=db.clinics.find(x=>x.id===id);c.services=c.services||[];c.services.push({name,price});save();renderClinicDashboard()}
function removeService(id,i){const c=db.clinics.find(x=>x.id===id);c.services.splice(i,1);save();renderClinicDashboard()}
function openClinicEditor(id){const c=db.clinics.find(x=>x.id===id);if(!c)return;openModal(`<h2>✏️ تعديل بيانات العيادة</h2><form class="form" onsubmit="saveClinicEdit(event,'${id}')"><label>اسم العيادة<input id="ecName" value="${esc(c.name)}" required></label><label>التخصص<select id="ecSpec">${specialties.map(s=>`<option ${s===c.specialty?'selected':''}>${s}</option>`).join('')}</select></label><label>اسم الطبيب<input id="ecDoctor" value="${esc(c.doctor||'')}"></label><label>العنوان<input id="ecAddress" value="${esc(c.address||'')}"></label><label>وصف العيادة<textarea id="ecDesc">${esc(c.description||'')}</textarea></label><div class="service-toggle"><label class="checkbox-line"><input id="ecMobileVisit" type="checkbox" ${c.mobileVisit?'checked':''}> 🏠 العيادة توفر طبيباً متنقلاً / زيارات منزلية</label><label>سعر الزيارة المنزلية (اختياري)<input id="ecMobilePrice" value="${esc(c.mobileVisitPrice||'')}" placeholder="مثلاً 250 DH"></label></div><label>صور جديدة JPG/PNG<input id="ecImages" type="file" accept="image/jpeg,image/png" multiple onchange="previewInput(event,'editPreview')"></label><div id="editPreview" class="image-preview"></div><div class="grid2"><label>Latitude<input id="ecLat" type="number" step="any" value="${c.location?.lat||''}"></label><label>Longitude<input id="ecLng" type="number" step="any" value="${c.location?.lng||''}"></label></div><button type="button" class="btn btn-soft" onclick="locateEdit()">📍 تحديد موقعي</button><h3>أوقات العمل</h3>${days.map(([k,n])=>{let x=c.schedule?.[k]||{};return `<div class="schedule-row"><b>${n}</b><input id="ef_${k}" type="time" value="${x.from||'09:00'}"><input id="et_${k}" type="time" value="${x.to||'18:00'}"><input class="switch" id="ee_${k}" type="checkbox" ${x.enabled?'checked':''}></div>`}).join('')}<button class="btn btn-primary">حفظ التعديلات</button></form>`)}
function locateEdit(){navigator.geolocation?.getCurrentPosition(p=>{ecLat.value=p.coords.latitude;ecLng.value=p.coords.longitude;toast('تم تحديد الموقع')},()=>toast('تعذر تحديد الموقع'))}
function saveClinicEdit(e,id){e.preventDefault();const c=db.clinics.find(x=>x.id===id);c.name=ecName.value;c.specialty=ecSpec.value;c.doctor=ecDoctor.value;c.address=ecAddress.value;c.description=ecDesc.value;c.mobileVisit=!!document.getElementById('ecMobileVisit')?.checked;c.mobileVisitPrice=document.getElementById('ecMobilePrice')?.value||'';c.location={lat:+ecLat.value||null,lng:+ecLng.value||null};days.forEach(([k])=>c.schedule[k]={enabled:document.getElementById('ee_'+k).checked,from:document.getElementById('ef_'+k).value,to:document.getElementById('et_'+k).value});const fs=[...ecImages.files];if(fs.length)readImages(fs,imgs=>{c.images=imgs;save();closeModal();toast('تم حفظ التعديلات');renderClinicDashboard()});else{save();closeModal();toast('تم حفظ التعديلات');renderClinicDashboard()}}
function openPayment(id){const c=db.clinics.find(x=>x.id===id);if(!c)return;const last=db.payments.filter(p=>p.clinicId===id).sort((a,b)=>b.date.localeCompare(a.date))[0];openModal(`<h2>💳 الاشتراك الشهري</h2><p>تفعيل حساب العيادة يتطلب اشتراكاً شهرياً.</p><div class="pay-summary"><span>الباقة الشهرية</span><br><b>99 DH</b><small> / 30 يوم</small></div><div class="detail-section"><h3>طريقة الدفع</h3><div class="payment-methods"><label class="pay-option active"><input type="radio" name="pm" value="card" checked onchange="paymentMethod=this.value"> 💳 بطاقة بنكية</label><label class="pay-option"><input type="radio" name="pm" value="cmi" onchange="paymentMethod=this.value"> 🏦 بوابة دفع مغربية</label><label class="pay-option"><input type="radio" name="pm" value="demo" onchange="paymentMethod=this.value"> 🧪 تجربة Frontend</label></div></div>${last?`<div class="notice" style="margin-top:10px">آخر عملية: ${last.status} · ${last.amount} DH</div>`:''}<button class="btn btn-primary" style="margin-top:12px;width:100%" onclick="createPayment('${id}')">متابعة الدفع 99 DH</button>`)}
function createPayment(id){const c=db.clinics.find(x=>x.id===id);const p={id:uid('pay'),clinicId:id,userId:current.id,amount:99,currency:'MAD',method:paymentMethod,status:'pending',date:new Date().toISOString()};db.payments.push(p);if(paymentMethod==='demo'){p.status='paid';activateClinicLocal(c);toast('تمت العملية التجريبية وتفعيل العيادة');}else{toast('تم إنشاء طلب الدفع. الربط الحقيقي بالبوابة يتم عبر Backend.');db.notifications.unshift({id:uid('n'),userId:current.id,text:'تم إنشاء طلب اشتراك بقيمة 99 DH. في النسخة المتصلة سيتم تحويلك لبوابة الدفع.',read:false,date:new Date().toISOString()})}save();closeModal();render()}
function activateClinicLocal(c){c.status='active';c.subscription={active:true,expires:new Date(Date.now()+30*864e5).toISOString().slice(0,10)}}
function openAuth(mode){const isLogin=mode==='login';openModal(`<h2>${isLogin?'🔐 تسجيل الدخول':'📝 إنشاء حساب'}</h2><p>${isLogin?'دخل للحساب ديالك.':'اختار نوع الحساب وأكمل المعلومات.'}</p>${!isLogin?`<div class="auth-switch"><button id="patientType" class="active" onclick="setRegisterType('patient')">👤 مريض</button><button id="clinicType" onclick="setRegisterType('clinic')">🏥 عيادة</button></div>`:''}<form class="form" onsubmit="${isLogin?'login(event)':'register(event)'}">${isLogin?`<label>البريد الإلكتروني أو الهاتف<input id="aLogin" required></label><label>كلمة المرور<input id="aPass" type="password" required></label><button class="btn btn-primary">تسجيل الدخول</button><button type="button" class="btn btn-soft" onclick="openAuth('register')">ليس لديك حساب؟ إنشاء حساب</button>`:`<label>الاسم الكامل<input id="rName" required></label><label>الهاتف<input id="rPhone" required></label><label>البريد الإلكتروني <small style="opacity:.7">اختياري</small><input id="rEmail" type="email" placeholder="example@email.com"></label><label>كلمة المرور<input id="rPass" type="password" minlength="6" required autocomplete="new-password"></label><label>تأكيد كلمة المرور<input id="rPass2" type="password" minlength="6" required autocomplete="new-password"></label><div id="clinicFields"></div><button class="btn btn-primary">إنشاء الحساب</button><button type="button" class="btn btn-soft" onclick="openAuth('login')">عندي حساب — تسجيل الدخول</button>`}</form>`);if(!isLogin)setRegisterType(registerType)}
function setRegisterType(t){registerType=t;document.getElementById('patientType')?.classList.toggle('active',t==='patient');document.getElementById('clinicType')?.classList.toggle('active',t==='clinic');const box=document.getElementById('clinicFields');if(box)box.innerHTML=t==='clinic'?clinicFields():''}
function clinicFields(){return `<div class="subscription"><b>⚠ الاشتراك الشهري إجباري</b><p>العيادة لن تظهر للمرضى حتى يتم الدفع والتفعيل.</p><div class="price">99 DH / شهر</div></div><label>اسم العيادة<input id="cName" required></label><label>التخصص<select id="cSpec">${specialties.map(s=>`<option>${s}</option>`).join('')}</select></label><label>اسم الطبيب<input id="cDoctor" required></label><label>العنوان<input id="cAddress" required></label><label>وصف العيادة<textarea id="cDesc"></textarea></label><label>صور JPG / PNG<input id="cImages" type="file" accept="image/jpeg,image/png" multiple required onchange="previewInput(event)"></label><div id="ePreview" class="image-preview"></div><div class="grid2"><label>Latitude<input id="cLat" type="number" step="any"></label><label>Longitude<input id="cLng" type="number" step="any"></label></div><button type="button" class="btn btn-soft" onclick="locate()">📍 تحديد موقعي</button><h3>أوقات العمل</h3>${days.map(([k,n])=>`<div class="schedule-row"><b>${n}</b><input id="cf_${k}" type="time" value="09:00"><input id="ct_${k}" type="time" value="18:00"><input class="switch" id="ce_${k}" type="checkbox" ${k!=='sun'?'checked':''}></div>`).join('')}`}
function locate(){navigator.geolocation?.getCurrentPosition(p=>{cLat.value=p.coords.latitude;cLng.value=p.coords.longitude;toast('تم تحديد الموقع')},()=>toast('تعذر تحديد الموقع'))}
function previewInput(e,target='ePreview'){const box=document.getElementById(target);if(!box)return;box.innerHTML='';[...e.target.files].slice(0,8).forEach(f=>{const r=new FileReader();r.onload=()=>box.insertAdjacentHTML('beforeend',`<img src="${r.result}" alt="preview">`);r.readAsDataURL(f)})}
function register(e){e.preventDefault();const email=(rEmail.value||'').trim().toLowerCase();const phone=(rPhone.value||'').trim();if(!/^0[5-7]\d{8}$/.test(phone))return toast('دخل رقم هاتف مغربي صحيح (05/06/07 + 8 أرقام)');if((rPass.value||'').length<6)return toast('كلمة المرور خاصها تكون 6 أحرف على الأقل');if(rPass.value!==rPass2.value)return toast('كلمتا المرور غير متطابقتين');if(db.users.some(u=>(email&&u.email?.toLowerCase()===email)||u.phone===phone))return toast('البريد أو الهاتف مستعمل من قبل');const u={id:uid('u'),name:rName.value,phone:rPhone.value,email:email || `${phone}@local.sihati`,password:rPass.value,type:registerType,favorites:[]};db.users.push(u);current={id:u.id,name:u.name,type:u.type,email:u.email,phone:u.phone,favorites:[]};if(registerType==='clinic'){const fs=[...cImages.files];readImages(fs,imgs=>{const c={id:uid('c'),ownerId:u.id,name:cName.value,specialty:cSpec.value,doctor:cDoctor.value,address:cAddress.value,description:cDesc.value,images:imgs,location:{lat:+cLat.value||null,lng:+cLng.value||null},schedule:{},services:[],doctors:[],verified:false,rating:0,reviews:[],status:'pending',subscription:{active:false,expires:null}};days.forEach(([k])=>c.schedule[k]={enabled:document.getElementById('ce_'+k).checked,from:document.getElementById('cf_'+k).value,to:document.getElementById('ct_'+k).value});db.clinics.push(c);save();closeModal();toast('تم إنشاء حساب العيادة. الآن كمل الاشتراك.');showScreen('clinicDashboard');setTimeout(()=>openPayment(c.id),250)})}else{save();closeModal();toast('تم إنشاء الحساب');showScreen('profile')}}
function readImages(fs,cb){if(!fs.length)return cb([]);let n=fs.length,arr=[];fs.forEach(f=>{if(!['image/jpeg','image/png'].includes(f.type)){if(!--n&&arr.length)cb(arr);return}let r=new FileReader();r.onload=()=>{arr.push(r.result);if(!--n)cb(arr)};r.readAsDataURL(f)})}
function login(e){e.preventDefault();const u=db.users.find(x=>x.email?.toLowerCase()===aLogin.value.toLowerCase()||x.phone===aLogin.value);if(!u||u.password!==aPass.value)return toast('بيانات الدخول غير صحيحة');current={id:u.id,name:u.name,type:u.type,email:u.email,phone:u.phone,favorites:u.favorites||[]};save();closeModal();toast('مرحبا '+u.name);showScreen(u.type==='clinic'?'clinicDashboard':'home')}
function logout(){current=null;save();closeDrawer();toast('تم تسجيل الخروج');showScreen('home')}
function openPasswordChange(){openModal(`<h2>🔐 تغيير كلمة المرور</h2><form class="form" onsubmit="changePassword(event)"><label>كلمة المرور الحالية<input id="oldPass" type="password" required></label><label>كلمة المرور الجديدة<input id="newPass" type="password" minlength="6" required></label><button class="btn btn-primary">حفظ</button></form>`)}
function changePassword(e){e.preventDefault();const u=db.users.find(x=>x.id===current.id);if(!u||u.password!==oldPass.value)return toast('كلمة المرور الحالية غير صحيحة');u.password=newPass.value;save();closeModal();toast('تم تغيير كلمة المرور')}
function reportClinic(id){if(!current)return openAuth('login');openModal(`<h2>⚠️ الإبلاغ عن العيادة</h2><form class="form" onsubmit="submitReport(event,'${id}')"><label>السبب<select id="repReason"><option>معلومات خاطئة</option><option>صور غير مناسبة</option><option>انتحال</option><option>عيادة غير موجودة</option><option>أخرى</option></select></label><label>التفاصيل<textarea id="repText" required></textarea></label><button class="btn btn-primary">إرسال البلاغ</button></form>`)}
function submitReport(e,id){e.preventDefault();db.reports.unshift({id:uid('rp'),clinicId:id,userId:current.id,reason:repReason.value,text:repText.value,status:'open',date:new Date().toISOString()});save();closeModal();toast('تم إرسال البلاغ للإدارة')}
function openAdminLogin(){openModal(`<h2>👑 الإدارة</h2><p>الحساب الإداري الوحيد لإدارة المنصة.</p><form class="form" onsubmit="adminLogin(event)"><label>البريد<input id="adEmail" type="email" required></label><label>كلمة المرور<input id="adPass" type="password" required></label><button class="btn btn-primary">دخول الإدارة</button></form>`)}
function adminLogin(e){e.preventDefault();if(adEmail.value!==db.admin.email||adPass.value!==db.admin.password)return toast('بيانات الإدارة غير صحيحة');closeModal();screen='admin';render()}
function renderAdmin(){const box=document.getElementById('adminBox'),active=clinics().length,pending=db.clinics.filter(c=>!isActive(c)).length,revenue=db.payments.filter(p=>p.status==='paid').reduce((a,p)=>a+p.amount,0);box.innerHTML=`<div class="admin-header"><span class="eyebrow">SIHATI ADMIN</span><h2>لوحة الإدارة</h2><p>إدارة العيادات، المستخدمين، الدفوعات، الصيدليات، التقييمات والبلاغات.</p></div><div class="admin-kpi" style="margin:12px 0"><div class="stat" style="background:white;border:1px solid #e2ebe8"><b>${active}</b><span>نشطة</span></div><div class="stat" style="background:white;border:1px solid #e2ebe8"><b>${pending}</b><span>تحتاج مراجعة</span></div><div class="stat" style="background:white;border:1px solid #e2ebe8"><b>${revenue} DH</b><span>إيرادات مسجلة</span></div><div class="stat" style="background:white;border:1px solid #e2ebe8"><b>${db.reports.filter(r=>r.status==='open').length}</b><span>بلاغات مفتوحة</span></div></div><div class="admin-nav">${['dashboard','clinics','emergency','mobile','payments','pharmacies','users','reviews','reports','logs'].map(x=>`<button class="${adminTab===x?'active':''}" onclick="adminTab='${x}';renderAdmin()">${({dashboard:'الرئيسية',clinics:'العيادات',payments:'الدفوعات',pharmacies:'الصيدليات',users:'الحسابات',reviews:'التقييمات',emergency:'الحالات العاجلة',mobile:'الطبيب المتنقل',reports:'البلاغات',logs:'السجل'})[x]}</button>`).join('')}</div><div class="panel">${adminContent()}</div>`}
function adminContent(){if(adminTab==='dashboard')return `<h3>ملخص الإدارة</h3><div class="notice">${pendingText()}</div><p>استعمل الأقسام أعلاه لمراجعة المحتوى وتفعيله أو تعطيله وحذفه حسب سياسة SIHATI.</p>`;if(adminTab==='clinics')return `<h3>العيادات</h3><div class="admin-list">${db.clinics.map(c=>`<div class="admin-item"><div><b>${esc(c.name)}</b><small>${esc(c.specialty)} · ${c.status} · ${c.subscription?.expires||'بدون اشتراك'}</small></div><div class="admin-actions">${!isActive(c)?`<button class="success" onclick="activateClinic('${c.id}')">تفعيل 30 يوم</button>`:`<button class="danger" onclick="deactivateClinic('${c.id}')">تعطيل</button>`}<button class="btn btn-soft" onclick="openClinicEditor('${c.id}')">تعديل</button><button class="${c.verified?'success':'btn-soft'}" onclick="toggleVerified('${c.id}')">${c.verified?'✓ موثقة':'توثيق'}</button><button class="danger" onclick="deleteClinic('${c.id}')">حذف</button></div></div>`).join('')||emptyCard('لا توجد عيادات')}</div>`;if(adminTab==='emergency')return `<h3>🚨 الحالات المستعجلة</h3><div class="admin-list">${(db.emergencies||[]).map(r=>{let u=db.users.find(x=>x.id===r.userId);return `<div class="admin-item emergency-admin"><div><b>${esc(r.type)} · ${esc(u?.name||'مريض')}</b><small>${esc(r.symptoms)} · 📞 ${esc(r.phone)} · 📍 ${esc(r.address)}</small></div><span class="status ${r.status}">${r.status==='new'?'جديد':r.status}</span></div>`}).join('')||emptyCard('لا توجد طلبات عاجلة')}</div>`;
if(adminTab==='mobile')return `<h3>🏠 طلبات الطبيب المتنقل</h3><div class="admin-list">${(db.mobileVisits||[]).map(r=>{let u=db.users.find(x=>x.id===r.userId);return `<div class="admin-item"><div><b>${esc(r.type)} · ${esc(r.specialty)}</b><small>${esc(u?.name||'مريض')} · 📞 ${esc(r.phone)} · 📍 ${esc(r.address)}${r.note?' · '+esc(r.note):''}</small></div><span class="status ${r.status}">${r.status==='new'?'جديد':r.status}</span></div>`}).join('')||emptyCard('لا توجد طلبات زيارات منزلية')}</div>`;
if(adminTab==='payments')return `<h3>الدفوعات</h3><div class="admin-list">${db.payments.map(p=>{let c=db.clinics.find(x=>x.id===p.clinicId);return `<div class="admin-item"><div><b>${esc(c?.name||'—')}</b><small>${p.amount} ${p.currency} · ${p.method} · ${p.status}</small></div><div class="admin-actions">${p.status!=='paid'?`<button class="success" onclick="markPaid('${p.id}')">تأكيد الدفع</button>`:`<span class="status confirmed">مدفوع</span>`}</div></div>`}).join('')||emptyCard('لا توجد دفوعات')}</div>`;if(adminTab==='pharmacies')return `<h3>صيدليات الحراسة</h3><form class="form" onsubmit="addPharmacy(event)"><label>الاسم<input id="pName" required></label><label>العنوان<input id="pAddress" required></label><label>الهاتف<input id="pPhone" required></label><div class="grid2"><label>من<input id="pFrom" type="time" value="20:00"></label><label>إلى<input id="pTo" type="time" value="08:00"></label></div><label>التاريخ<input id="pDate" type="date"></label><div class="grid2"><label>Latitude<input id="pLat" type="number" step="any"></label><label>Longitude<input id="pLng" type="number" step="any"></label></div><button class="btn btn-primary">إضافة صيدلية</button></form><hr>${db.pharmacies.map(p=>`<div class="admin-item"><div><b>${esc(p.name)}</b><small>${esc(p.address)} · ${esc(p.phone)} · ${p.date||'يومي'}</small></div><div class="admin-actions"><button class="btn btn-soft" onclick="editPharmacy('${p.id}')">تعديل</button><button class="danger" onclick="deletePharmacy('${p.id}')">حذف</button></div></div>`).join('')}`;if(adminTab==='users')return `<h3>الحسابات</h3><div class="admin-list">${db.users.map(u=>`<div class="admin-item"><div><b>${esc(u.name)}</b><small>${esc(u.email)} · ${u.type}</small></div><button class="danger" onclick="deleteUser('${u.id}')">حذف</button></div>`).join('')}</div>`;if(adminTab==='reviews')return `<h3>التقييمات</h3><div class="admin-list">${db.reviews.map(r=>`<div class="admin-item"><div><b>⭐ ${r.rating}/5</b><small>${esc(r.text)}</small></div><button class="danger" onclick="deleteReview('${r.id}')">حذف</button></div>`).join('')||emptyCard('لا توجد تقييمات')}</div>`;if(adminTab==='reports')return `<h3>البلاغات</h3><div class="admin-list">${db.reports.map(r=>{let c=db.clinics.find(x=>x.id===r.clinicId);return `<div class="admin-item"><div><b>${esc(c?.name||'عيادة')}</b><small>${esc(r.reason)} · ${esc(r.text)}</small></div><div class="admin-actions"><button class="success" onclick="closeReport('${r.id}')">إغلاق</button><button class="danger" onclick="deleteReport('${r.id}')">حذف</button></div></div>`}).join('')||emptyCard('لا توجد بلاغات')}</div>`;return `<h3>Audit Log</h3><div class="admin-list">${db.logs.map(l=>`<div class="admin-item"><div><b>${esc(l.action)}</b><small>${esc(l.details)} · ${new Date(l.date).toLocaleString()}</small></div></div>`).join('')||emptyCard('السجل فارغ')}</div>`}
function pendingText(){const n=db.clinics.filter(c=>!isActive(c)).length;return n?`كاينين ${n} عيادات خاصها مراجعة/تفعيل.`:'ما كايناش عيادات معلقة حالياً.'}
function toggleVerified(id){const c=db.clinics.find(x=>x.id===id);if(!c)return;c.verified=!c.verified;log(c.verified?'verify_clinic':'unverify_clinic',c.name);save();toast(c.verified?'تم توثيق العيادة':'تم إلغاء التوثيق');renderAdmin()}
function activateClinic(id){let c=db.clinics.find(x=>x.id===id);if(!c)return;c.status='active';c.subscription={active:true,expires:new Date(Date.now()+30*864e5).toISOString().slice(0,10)};log('activate_clinic',c.name);save();toast('تم التفعيل 30 يوماً');renderAdmin()}
function deactivateClinic(id){let c=db.clinics.find(x=>x.id===id);c.status='suspended';c.subscription.active=false;log('deactivate_clinic',c.name);save();renderAdmin()}
function deleteClinic(id){if(!confirm('حذف العيادة نهائياً؟'))return;let c=db.clinics.find(x=>x.id===id);db.clinics=db.clinics.filter(x=>x.id!==id);log('delete_clinic',c?.name||id);save();renderAdmin()}
function markPaid(id){let p=db.payments.find(x=>x.id===id);p.status='paid';let c=db.clinics.find(x=>x.id===p.clinicId);activateClinicLocal(c);db.notifications.unshift({id:uid('n'),userId:c.ownerId,text:'تم تأكيد اشتراك عيادتك وتفعيلها لمدة 30 يوماً.',read:false,date:new Date().toISOString()});log('mark_payment_paid',p.id);save();toast('تم تأكيد الدفع وتفعيل العيادة');renderAdmin()}
function addPharmacy(e){e.preventDefault();db.pharmacies.push({id:uid('p'),name:pName.value,address:pAddress.value,phone:pPhone.value,from:pFrom.value,to:pTo.value,date:pDate.value||'',lat:+pLat.value||null,lng:+pLng.value||null});log('add_pharmacy',pName.value);save();toast('تمت إضافة الصيدلية');renderAdmin()}
function editPharmacy(id){const p=db.pharmacies.find(x=>x.id===id);if(!p)return;openModal(`<h2>✏️ تعديل الصيدلية</h2><form class="form" onsubmit="savePharmacy(event,'${id}')"><label>الاسم<input id="epName" value="${esc(p.name)}" required></label><label>العنوان<input id="epAddress" value="${esc(p.address)}" required></label><label>الهاتف<input id="epPhone" value="${esc(p.phone)}" required></label><div class="grid2"><label>من<input id="epFrom" type="time" value="${p.from||'20:00'}"></label><label>إلى<input id="epTo" type="time" value="${p.to||'08:00'}"></label></div><label>التاريخ<input id="epDate" type="date" value="${p.date||''}"></label><button class="btn btn-primary">حفظ</button></form>`)}
function savePharmacy(e,id){e.preventDefault();let p=db.pharmacies.find(x=>x.id===id);Object.assign(p,{name:epName.value,address:epAddress.value,phone:epPhone.value,from:epFrom.value,to:epTo.value,date:epDate.value});save();closeModal();renderAdmin();toast('تم تعديل الصيدلية')}
function deletePharmacy(id){db.pharmacies=db.pharmacies.filter(p=>p.id!==id);log('delete_pharmacy',id);save();renderAdmin()}
function deleteUser(id){if(id===current?.id)return toast('ما يمكنش تحذف الحساب الحالي من هنا');db.users=db.users.filter(u=>u.id!==id);save();renderAdmin()}
function deleteReview(id){db.reviews=db.reviews.filter(r=>r.id!==id);db.clinics.forEach(c=>c.reviews=(c.reviews||[]).filter(r=>r.id!==id));save();renderAdmin()}
function closeReport(id){const r=db.reports.find(x=>x.id===id);if(r)r.status='closed';save();renderAdmin()}
function deleteReport(id){db.reports=db.reports.filter(x=>x.id!==id);save();renderAdmin()}
function requestLocation(){if(!navigator.geolocation)return toast('المتصفح لا يدعم الموقع');navigator.geolocation.getCurrentPosition(pos=>{const lat=pos.coords.latitude,lng=pos.coords.longitude;const arr=clinics().map(c=>({...c,distance:c.location?.lat?distanceKm(lat,lng,c.location.lat,c.location.lng):9999})).sort((a,b)=>a.distance-b.distance);document.getElementById('searchResults').innerHTML=arr.map(c=>clinicCard(c)+`<div class="mini-badge">📍 ${c.distance<9999?c.distance.toFixed(1)+' km':'المسافة غير متاحة'}</div>`).join('')||emptyCard('لا توجد عيادات');},()=>toast('خاصك تسمح بالموقع'))}
function distanceKm(a,b,c,d){const R=6371,x=(c-a)*Math.PI/180,y=(d-b)*Math.PI/180;const q=Math.sin(x/2)**2+Math.cos(a*Math.PI/180)*Math.cos(c*Math.PI/180)*Math.sin(y/2)**2;return R*2*Math.atan2(Math.sqrt(q),Math.sqrt(1-q))}
function openModal(content){document.getElementById('modalRoot').innerHTML=`<div class="modal"><div class="backdrop" onclick="closeModal()"></div><div class="modal-card"><button class="close" onclick="closeModal()">×</button>${content}</div></div>`}
function closeModal(){document.getElementById('modalRoot').innerHTML=''}
render();

/* =========================
   SIHATI — PHASE 2
   Notifications + trusted reviews + favorites + chat
   ========================= */

// Persistent chat store (Frontend demo)
db.messages = db.messages || [];
let chatClinicId = null;


function addNotification(userId,text,type='general'){
  db.notifications.unshift({id:uid('n'),userId,text,type,read:false,date:new Date().toISOString()});
}

function notifyAppointmentParties(a,status){
  const clinic=db.clinics.find(c=>c.id===a.clinicId);
  const patient=db.users.find(u=>u.id===a.userId);
  const clinicOwner=clinic?.ownerId;
  const labels={confirmed:'مؤكد',completed:'مكتمل',cancelled:'ملغى',pending:'في الانتظار'};
  addNotification(a.userId,`تم تحديث موعدك مع ${clinic?.name||'العيادة'} إلى: ${labels[status]||status}.`,'appointment');
  if(clinicOwner) addNotification(clinicOwner,`تحديث موعد ${patient?.name||'مريض'}: ${labels[status]||status} — ${a.date} ${a.time}.`,'appointment');
}

// Replace booking confirmation so both patient and clinic receive notifications.
confirmBooking=function(e){
  e.preventDefault();
  if(!bookingDate||!bookingTime)return toast('اختار اليوم والساعة');
  const a={id:uid('a'),clinicId:selectedClinic.id,userId:current.id,date:bookingDate,time:bookingTime,type:bType.value,note:bNote.value,status:'pending',createdAt:new Date().toISOString()};
  db.appointments.push(a);
  addNotification(current.id,`تم إرسال طلب موعدك مع ${selectedClinic.name} بتاريخ ${bookingDate} على الساعة ${bookingTime}.`,'appointment');
  const clinic=db.clinics.find(c=>c.id===a.clinicId);
  if(clinic?.ownerId)addNotification(clinic.ownerId,`حجز جديد من ${current.name} بتاريخ ${bookingDate} على الساعة ${bookingTime}.`,'appointment');
  save();closeModal();toast('تم إرسال طلب الموعد');showScreen('appointments');
};

// Replace appointment status updates with richer notifications.
setAppointmentStatus=function(id,status){
  const a=db.appointments.find(x=>x.id===id); if(!a)return;
  a.status=status;
  notifyAppointmentParties(a,status);
  save();
  if(screen==='appointments')renderAppointments(); else render();
  toast('تم تحديث الموعد');
};

// Trusted reviews: only a completed appointment can be reviewed, once per appointment.
reviewAppointment=function(id){
  const a=db.appointments.find(x=>x.id===id),c=db.clinics.find(x=>x.id===a?.clinicId);
  if(!a||!c)return;
  if(a.userId!==current?.id||a.status!=='completed')return toast('التقييم متاح فقط بعد إتمام الموعد');
  if(db.reviews.some(r=>r.appointmentId===id))return toast('سبق ليك قيمتي هاد الموعد');
  openModal(`<h2>⭐ تقييم موثوق</h2><p>${esc(c.name)}</p><div class="verified-review-note">✓ التقييم متاح فقط بعد موعد مكتمل</div><form class="form" onsubmit="submitReview(event,'${id}')"><label>التقييم<select id="revRating"><option value="5">⭐⭐⭐⭐⭐</option><option value="4">⭐⭐⭐⭐</option><option value="3">⭐⭐⭐</option><option value="2">⭐⭐</option><option value="1">⭐</option></select></label><label>تعليق<textarea id="revText" required maxlength="600"></textarea></label><button class="btn btn-primary">إرسال التقييم</button></form>`);
};

submitReview=function(e,id){
  e.preventDefault();
  const a=db.appointments.find(x=>x.id===id),c=db.clinics.find(x=>x.id===a?.clinicId);
  if(!a||!c||a.userId!==current?.id||a.status!=='completed')return toast('التقييم متاح فقط بعد إتمام الموعد');
  if(db.reviews.some(r=>r.appointmentId===id))return toast('سبق ليك قيمتي هاد الموعد');
  const r={id:uid('r'),appointmentId:id,clinicId:c.id,userId:current.id,userName:current.name,rating:+revRating.value,text:revText.value.trim(),status:'published',verified:true,date:new Date().toISOString()};
  db.reviews.push(r);c.reviews=c.reviews||[];c.reviews.push(r);c.rating=+(c.reviews.reduce((s,x)=>s+x.rating,0)/c.reviews.length).toFixed(1);
  addNotification(c.ownerId,`تقييم جديد موثوق لعيادتك: ⭐ ${r.rating}/5.`,'review');
  save();closeModal();toast('شكراً على تقييمك ⭐');
};

// Trusted-review badge in clinic cards/details.
const phase2OriginalClinicCard=clinicCard;
clinicCard=function(c){
  const html=phase2OriginalClinicCard(c);
  if(!c)return html;
  return html.replace('</article>',`<div class="trusted-count">${(c.reviews||[]).filter(r=>r.verified).length} تقييم موثوق ✓</div></article>`);
};

function chatLabel(c){return c?.name||'العيادة'}
function chatForPatient(){return db.clinics.filter(c=>isActive(c)&&db.messages.some(m=>m.patientId===current?.id&&m.clinicId===c.id))}
function chatForClinic(){const c=db.clinics.find(x=>x.ownerId===current?.id);return c?db.users.filter(u=>u.type==='patient'&&db.messages.some(m=>m.patientId===u.id&&m.clinicId===c.id)):[]}
function getMessages(clinicId,patientId){return db.messages.filter(m=>m.clinicId===clinicId&&m.patientId===patientId).sort((a,b)=>new Date(a.date)-new Date(b.date))}

function openChat(clinicId,patientId=null){
  if(!current)return openAuth('login');
  const c=db.clinics.find(x=>x.id===clinicId); if(!c)return;
  const pid=current.type==='patient'?current.id:patientId;
  if(!pid)return toast('اختار المريض أولاً');
  chatClinicId=clinicId;
  const title=current.type==='clinic'?(db.users.find(u=>u.id===pid)?.name||'مريض'):c.name;
  openModal(`<div class="chat-head"><div><span class="eyebrow">💬 SIHATI CHAT</span><h2>${esc(title)}</h2></div><span class="mini-badge">${c.verified?'✓ موثقة':''}</span></div><div id="chatMessages" class="chat-messages"></div><form class="chat-form" onsubmit="sendChat(event,'${clinicId}','${pid}')"><input id="chatText" maxlength="500" placeholder="اكتب رسالتك..." autocomplete="off" required><button class="btn btn-primary">إرسال</button></form>`);
  renderChatMessages(clinicId,pid);
}
function renderChatMessages(clinicId,pid){
  const box=document.getElementById('chatMessages'); if(!box)return;
  const arr=getMessages(clinicId,pid);
  box.innerHTML=arr.map(m=>`<div class="chat-bubble ${m.senderId===current?.id?'mine':'theirs'}"><div>${esc(m.text)}</div><small>${new Date(m.date).toLocaleString(lang==='ar'?'ar-MA':lang==='fr'?'fr-FR':'en-US')}</small></div>`).join('')||`<div class="empty">ابدأ المحادثة برسالة قصيرة.</div>`;
  box.scrollTop=box.scrollHeight;
}
function sendChat(e,clinicId,pid){
  e.preventDefault();const text=chatText.value.trim();if(!text)return;
  const m={id:uid('m'),clinicId,patientId:pid,senderId:current.id,text,date:new Date().toISOString()};
  db.messages.push(m);
  const receiver=current.type==='patient'?db.clinics.find(c=>c.id===clinicId)?.ownerId:pid;
  if(receiver)addNotification(receiver,`💬 رسالة جديدة من ${current.name}.`,'chat');
  save();chatText.value='';renderChatMessages(clinicId,pid);render();
}

function chatFromClinic(id){openChat(id)}

function renderChatHub(){
  const box=document.getElementById('chatHubBox');
  if(!current)return box.innerHTML=`${emptyCard('خاصك تسجل الدخول باش تستعمل المحادثة')}<button class="btn btn-primary" onclick="openAuth('login')">تسجيل الدخول</button>`;
  if(current.type==='patient'){
    const arr=chatForPatient();
    box.innerHTML=arr.map(c=>{const msgs=getMessages(c.id,current.id),last=msgs[msgs.length-1];return `<button class="chat-thread" onclick="openChat('${c.id}')"><span class="thread-avatar">🏥</span><span><b>${esc(c.name)}</b><small>${esc(last?.text||'ابدأ محادثة')}</small></span><span>›</span></button>`}).join('')||emptyCard('ما عندك حتى محادثة. دخل لصفحة عيادة وابدأ التواصل معها.');
  }else if(current.type==='clinic'){
    const c=db.clinics.find(x=>x.ownerId===current.id),arr=chatForClinic();
    box.innerHTML=arr.map(u=>{const msgs=getMessages(c.id,u.id),last=msgs[msgs.length-1];return `<button class="chat-thread" onclick="openChat('${c.id}','${u.id}')"><span class="thread-avatar">👤</span><span><b>${esc(u.name)}</b><small>${esc(last?.text||'محادثة جديدة')}</small></span><span>›</span></button>`}).join('')||emptyCard('ما عندك حتى محادثة مع المرضى.');
  }
}

