function clinicOfCurrent(){return current?.type==='clinic'?db.clinics.find(c=>c.ownerId===current.id):null}
function recordClinicView(id){const c=db.clinics.find(x=>x.id===id);if(c){c.analytics=c.analytics||{views:0,bookings:0,completed:0};c.analytics.views++;save()}}
function money(n){return `${Number(n||0).toFixed(2)} DH`}
function invoiceForPayment(p){
  let c=db.clinics.find(x=>x.id===p.clinicId); if(!c)return;
  if(!db.invoices.some(i=>i.paymentId===p.id)) db.invoices.unshift({id:uid('inv'),paymentId:p.id,clinicId:c.id,number:'SIH-'+Date.now().toString().slice(-8),amount:p.amount,currency:'DH',date:new Date().toISOString(),status:'paid'});
}
function openInvoice(id){
 const i=db.invoices.find(x=>x.id===id); if(!i)return toast('الفاتورة غير موجودة'); const c=db.clinics.find(x=>x.id===i.clinicId);
 openModal(`<div class="invoice-card"><div class="invoice-top"><div><span class="eyebrow">SIHATI</span><h2>فاتورة الاشتراك</h2></div><b>${esc(i.number)}</b></div><div class="invoice-row"><span>العيادة</span><b>${esc(c?.name||'—')}</b></div><div class="invoice-row"><span>الخدمة</span><b>اشتراك SIHATI الشهري</b></div><div class="invoice-row"><span>التاريخ</span><b>${new Date(i.date).toLocaleDateString(lang==='ar'?'ar-MA':lang==='fr'?'fr-FR':'en-US')}</b></div><div class="invoice-total"><span>المجموع</span><strong>${money(i.amount)}</strong></div><button class="btn btn-primary" onclick="window.print()">🖨️ طباعة / حفظ PDF</button></div>`)
}
function clinicAnalytics(c){
 const apps=db.appointments.filter(a=>a.clinicId===c.id); const completed=apps.filter(a=>a.status==='completed').length;
 c.analytics=c.analytics||{views:0,bookings:0,completed:0};c.analytics.bookings=apps.length;c.analytics.completed=completed;
 const rev=(c.reviews||[]).length?((c.reviews||[]).reduce((s,r)=>s+r.rating,0)/(c.reviews||[]).length).toFixed(1):'0.0';
 return `<div class="business-kpis"><div><b>${c.analytics.views}</b><span>مشاهدات</span></div><div><b>${apps.length}</b><span>حجوزات</span></div><div><b>${completed}</b><span>مواعيد مكتملة</span></div><div><b>⭐ ${rev}</b><span>التقييم</span></div></div>`;
}
function clinicSubscription(c){
 const exp=c.subscription?.expires?new Date(c.subscription.expires+'T23:59:59'):null;const days=exp?Math.ceil((exp-new Date())/86400000):0;
 return `<div class="subscription-card"><div><span class="eyebrow">الاشتراك</span><h3>${c.subscription?.active?'🟢 الاشتراك نشط':'🔴 الاشتراك غير نشط'}</h3><p>${c.subscription?.active?`ينتهي في ${c.subscription.expires} — ${Math.max(days,0)} يوم متبقي`:'الاشتراك الشهري إجباري لتفعيل ظهور العيادة.'}</p></div><div class="subscription-price">99 DH<small>/ شهر</small></div><button class="btn btn-primary" onclick="openPayment('${c.id}')">${c.subscription?.active?'تجديد الاشتراك':'الاشتراك الآن'}</button></div>`;
}
function openAdForm(id=null){
 const a=id?db.ads.find(x=>x.id===id):null;
 openModal(`<h2>📢 ${a?'تعديل الإعلان':'إضافة إعلان'}</h2><form class="form" onsubmit="saveAd(event,'${id||''}')"><label>العنوان<input id="adTitle" required value="${esc(a?.title||'')}"></label><label>الوصف<textarea id="adText" required>${esc(a?.text||'')}</textarea></label><label>رابط اختياري<input id="adUrl" value="${esc(a?.url||'')}"></label><div class="grid2"><label>يبدأ<input id="adFrom" type="date" required value="${a?.from||''}"></label><label>ينتهي<input id="adTo" type="date" required value="${a?.to||''}"></label></div><button class="btn btn-primary">حفظ الإعلان</button></form>`)
}
function saveAd(e,id){e.preventDefault();const a=id?db.ads.find(x=>x.id===id):{id:uid('ad')};Object.assign(a,{title:adTitle.value,text:adText.value,url:adUrl.value,from:adFrom.value,to:adTo.value,active:true});if(!id)db.ads.unshift(a);log(id?'edit_ad':'create_ad',a.title);save();closeModal();renderAdmin();toast('تم حفظ الإعلان')}
function deleteAd(id){db.ads=db.ads.filter(a=>a.id!==id);log('delete_ad',id);save();renderAdmin();toast('تم حذف الإعلان')}
function activeAds(){const now=new Date().toISOString().slice(0,10);return db.ads.filter(a=>a.active!==false&&(!a.from||a.from<=now)&&(!a.to||a.to>=now))}
function renderAds(){const box=document.getElementById('adsBox');if(!box)return;box.innerHTML=activeAds().map(a=>`<article class="ad-card"><span class="eyebrow">إعلان SIHATI</span><h3>${esc(a.title)}</h3><p>${esc(a.text)}</p>${a.url?`<a class="btn btn-soft" href="${esc(a.url)}" target="_blank" rel="noopener">المزيد ↗</a>`:''}</article>`).join('')||emptyCard('لا توجد إعلانات حالياً')}

