// Extend local data safely
function ensureServiceStores(){
  db.emergencies=db.emergencies||[];
  db.mobileVisits=db.mobileVisits||[];
  db.messages=db.messages||[];
  db.notifications=db.notifications||[];
  db.reviews=db.reviews||[];
  db.clinics=db.clinics||[];
  db.clinics.forEach(c=>{c.doctors=c.doctors||[];c.services=c.services||[];c.reviews=c.reviews||[];c.mobileVisit=!!c.mobileVisit;});
}
ensureServiceStores();
save();

function pushNotification(userId,text,type='general'){
  db.notifications.unshift({id:uid('n'),userId,text,type,read:false,date:new Date().toISOString()});
  try{
    if(userId===current?.id && 'Notification' in window && Notification.permission==='granted') new Notification('SIHATI',{body:text,icon:'assets/icon-512.png'});
  }catch(_e){}
}
function requestBrowserNotifications(){
  if(!('Notification' in window)) return toast('الإشعارات غير مدعومة في هذا الجهاز');
  Notification.requestPermission().then(p=>toast(p==='granted'?'تم تفعيل إشعارات SIHATI 🔔':'لم يتم تفعيل الإشعارات'));
}
function getCurrentPositionPromise(){
  return new Promise((resolve,reject)=>{
    if(!navigator.geolocation) return reject(new Error('unsupported'));
    navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:10000,maximumAge:60000});
  });
}
function setGps(prefix,callback){
  getCurrentPositionPromise().then(pos=>{
    const lat=+pos.coords.latitude.toFixed(6),lng=+pos.coords.longitude.toFixed(6);
    const latEl=document.getElementById(prefix+'Lat'),lngEl=document.getElementById(prefix+'Lng');
    if(latEl)latEl.value=lat;if(lngEl)lngEl.value=lng;
    const status=document.getElementById(prefix+'GpsStatus');if(status)status.innerHTML='📍 تم تحديد موقعك بدقة';
    if(callback)callback(lat,lng);
  }).catch(()=>toast('تعذر تحديد الموقع. فعّل GPS واسمح بالوصول للموقع.'));
}
function googleMapsLink(lat,lng){return lat&&lng?`https://www.google.com/maps?q=${encodeURIComponent(lat+','+lng)}`:''}
function serviceStatusLabel(s){return ({new:'جديد',searching:'جاري البحث',accepted:'تم القبول',on_the_way:'الطبيب في الطريق',arrived:'وصل مقدم الخدمة',completed:'مكتمل',cancelled:'ملغى'})[s]||s}
function serviceStatusClass(s){return s==='completed'?'completed':s==='cancelled'?'cancelled':s==='accepted'||s==='on_the_way'||s==='arrived'?'confirmed':'pending'}
function providerCandidates(type,specialty){
  return clinics().flatMap(c=>(c.doctors||[]).filter(d=>d.available!==false && (d.mobileVisit||c.mobileVisit) && (!specialty||d.specialty===specialty||c.specialty===specialty)).map(d=>({clinic:c,doctor:d})));
}

// Rich emergency request form with GPS and status tracking.
screens.emergency=()=>`<div class="screen service-screen"><div class="service-hero emergency-hero"><span>🚨</span><div><span class="eyebrow">خدمة عاجلة • 24/7</span><h2>حالة مستعجلة</h2><p>اطلب طبيباً أو ممرضاً قريباً منك. سنحاول توجيه الطلب إلى مقدم خدمة متاح.</p></div></div><div class="form-card emergency-form"><div class="alert-note">⚠️ إذا كانت الحالة تهدد الحياة، اتصل فوراً بخدمات الطوارئ المحلية. SIHATI ليست بديلاً عن الإسعاف.</div><form class="form" onsubmit="submitEmergencyV7(event)"><div class="choice-grid"><label class="choice-card"><input type="radio" name="emProvider" id="emDoctor" value="طبيب" checked><span>👨‍⚕️</span><b>طبيب</b><small>فحص وتدخل طبي</small></label><label class="choice-card"><input type="radio" name="emProvider" value="ممرض / ممرضة"><span>🧑‍⚕️</span><b>ممرض</b><small>رعاية وتمريض سريع</small></label></div><label>نوع الحالة<select id="emSeverity"><option>حالة تحتاج تدخلاً سريعاً</option><option>ألم شديد</option><option>جرح أو نزيف</option><option>حمى أو تدهور مفاجئ</option><option>صعوبة في الحركة</option><option>أخرى</option></select></label><label>الأعراض والتفاصيل<textarea id="emSymptoms" required placeholder="اشرح الحالة باختصار..."></textarea></label><label>رقم الهاتف<input id="emPhone" inputmode="tel" required placeholder="06XXXXXXXX" value="${esc(current?.phone||'')}"></label><label>العنوان<textarea id="emAddress" required placeholder="الحي، الشارع، رقم المنزل..."></textarea></label><div class="gps-box"><div><b>📍 موقعك الحالي</b><small id="emGpsStatus">لم يتم تحديد الموقع بعد</small></div><button type="button" class="btn btn-soft" onclick="setGps('em')">تحديد GPS</button><input id="emLat" type="hidden"><input id="emLng" type="hidden"></div><button class="btn btn-emergency emergency-submit">🚨 أرسل طلب المساعدة الآن</button></form></div><div id="emergencyStatus">${renderMyEmergencyStatus()}</div></div>`;

function renderMyEmergencyStatus(){
  if(!current)return '';
  const r=db.emergencies.find(x=>x.userId===current.id && !['completed','cancelled'].includes(x.status));
  if(!r)return '';
  return `<div class="service-tracker"><div class="tracker-top"><div><span class="eyebrow">طلبك الحالي</span><h3>🚨 ${esc(r.type)}</h3></div><span class="status ${serviceStatusClass(r.status)}">${serviceStatusLabel(r.status)}</span></div><div class="tracker-steps">${['new','accepted','on_the_way','arrived'].map((s,i)=>`<div class="tracker-step ${['new','accepted','on_the_way','arrived'].indexOf(r.status)>=i?'done':''}"><span>${i+1}</span><small>${serviceStatusLabel(s)}</small></div>`).join('')}</div><div class="tracker-actions">${r.provider?.phone?`<a class="btn btn-primary" href="tel:${esc(r.provider.phone)}">📞 اتصال</a>`:''}${r.lat&&r.lng?`<a class="btn btn-soft" target="_blank" href="${googleMapsLink(r.lat,r.lng)}">📍 الموقع</a>`:''}<button class="btn btn-danger-soft" onclick="cancelEmergencyV7('${r.id}')">إلغاء الطلب</button></div></div>`;
}

function submitEmergencyV7(e){
  e.preventDefault(); if(!current)return openAuth('login');
  const type=document.querySelector('input[name="emProvider"]:checked')?.value||'طبيب';
  const r={id:uid('em'),userId:current.id,type,symptoms:emSymptoms.value.trim(),severity:emSeverity.value,phone:emPhone.value.trim(),address:emAddress.value.trim(),lat:+emLat.value||null,lng:+emLng.value||null,status:'searching',createdAt:new Date().toISOString()};
  const candidates=providerCandidates(type,null);
  if(candidates.length){const p=candidates[0];r.provider={clinicId:p.clinic.id,doctorId:p.doctor.id,name:p.doctor.name,phone:p.doctor.phone||p.clinic.phone||''};r.status='searching';}
  db.emergencies.unshift(r);pushNotification(current.id,'🚨 تم استلام طلب الحالة المستعجلة وبدأ البحث عن مقدم خدمة.','emergency');save();requestBrowserNotifications();
  render();toast('تم إرسال طلب المساعدة 🚨');
}
function cancelEmergencyV7(id){const r=db.emergencies.find(x=>x.id===id);if(!r||r.userId!==current?.id)return;r.status='cancelled';pushNotification(current.id,'تم إلغاء طلب الحالة المستعجلة.','emergency');save();render();}

// Home-visit flow with provider discovery, date/time and GPS.
screens.mobileDoctor=()=>{const specs=[...new Set(clinics().filter(c=>c.mobileVisit).map(c=>c.specialty).concat(specialties))];return `<div class="screen service-screen"><div class="service-hero mobile-hero"><span>🏠</span><div><span class="eyebrow">رعاية منزلية</span><h2>طبيب متنقل</h2><p>طبيب أو ممرض يجي عندك للدار حسب التخصص والتوفر.</p></div></div><div class="form-card"><form class="form" onsubmit="submitMobileVisitV7(event)"><label>التخصص المطلوب<select id="mvSpec">${specs.map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label>الخدمة المطلوبة<select id="mvType"><option>زيارة طبيب منزلية</option><option>زيارة ممرض / ممرضة</option><option>متابعة منزلية</option><option>حقن / تغيير ضماد</option><option>فحص منزلي</option><option>رعاية مسنين</option></select></label><div class="choice-grid compact"><label class="choice-card"><input type="radio" name="mvWhen" value="now" checked><span>⚡</span><b>الآن</b><small>أقرب مقدم خدمة</small></label><label class="choice-card"><input type="radio" name="mvWhen" value="later"><span>📅</span><b>موعد لاحق</b><small>حدد الوقت المناسب</small></label></div><div id="mvSchedule" class="schedule-inline hidden"><div class="grid2"><label>التاريخ<input id="mvDate" type="date"></label><label>الساعة<input id="mvTime" type="time"></label></div></div><label>الهاتف<input id="mvPhone" inputmode="tel" required value="${esc(current?.phone||'')}"></label><label>العنوان<textarea id="mvAddress" required placeholder="الحي، الشارع، رقم المنزل..."></textarea></label><div class="gps-box"><div><b>📍 تحديد موقع المنزل</b><small id="mvGpsStatus">الموقع يساعد مقدم الخدمة على الوصول بسرعة</small></div><button type="button" class="btn btn-soft" onclick="setGps('mv')">تحديد GPS</button><input id="mvLat" type="hidden"><input id="mvLng" type="hidden"></div><label>ملاحظات<textarea id="mvNote" placeholder="أعراض، اسم المريض، معلومات إضافية..."></textarea></label><button class="btn btn-primary">🏠 تأكيد طلب الزيارة</button></form></div><div class="section"><div class="notice"><b>كيف تعمل؟</b><br>أرسل الطلب → نبحث عن مقدم خدمة متاح → يقبل الطلب → تتوصل بحالة الطبيب ومعلومات الاتصال.</div></div><div id="mobileStatus">${renderMyMobileStatus()}</div></div>`};

function bindMobileSchedule(){document.querySelectorAll('input[name="mvWhen"]').forEach(x=>x.addEventListener('change',()=>{document.getElementById('mvSchedule')?.classList.toggle('hidden',x.value!=='later'||!x.checked)}));}
function renderMyMobileStatus(){if(!current)return '';const r=db.mobileVisits.find(x=>x.userId===current.id&&!['completed','cancelled'].includes(x.status));if(!r)return '';return `<div class="service-tracker"><div class="tracker-top"><div><span class="eyebrow">زيارة منزلية</span><h3>🏠 ${esc(r.specialty)}</h3><small>${esc(r.type)}</small></div><span class="status ${serviceStatusClass(r.status)}">${serviceStatusLabel(r.status)}</span></div><div class="provider-card">${r.provider?`<div class="provider-avatar">👨‍⚕️</div><div><b>${esc(r.provider.name)}</b><small>${esc(r.provider.specialty||r.specialty)} · ${esc(r.provider.clinicName||'')}</small></div>`:`<div class="provider-avatar">⌛</div><div><b>جاري البحث عن مقدم خدمة</b><small>سيظهر الطبيب هنا بعد القبول</small></div>`}</div><div class="tracker-actions">${r.provider?.phone?`<a class="btn btn-primary" href="tel:${esc(r.provider.phone)}">📞 اتصال</a>`:''}${r.lat&&r.lng?`<a class="btn btn-soft" target="_blank" href="${googleMapsLink(r.lat,r.lng)}">📍 الموقع</a>`:''}<button class="btn btn-danger-soft" onclick="cancelMobileVisitV7('${r.id}')">إلغاء</button></div></div>`}
function submitMobileVisitV7(e){e.preventDefault();if(!current)return openAuth('login');const when=document.querySelector('input[name="mvWhen"]:checked')?.value||'now';const r={id:uid('mv'),userId:current.id,specialty:mvSpec.value,type:mvType.value,when,date:when==='later'?mvDate.value:'',time:when==='later'?mvTime.value:'',phone:mvPhone.value.trim(),address:mvAddress.value.trim(),lat:+mvLat.value||null,lng:+mvLng.value||null,note:mvNote.value.trim(),status:'searching',createdAt:new Date().toISOString()};const candidates=providerCandidates(r.type.includes('ممرض')?'ممرض':null,r.specialty);if(candidates.length){const p=candidates[0];r.provider={clinicId:p.clinic.id,doctorId:p.doctor.id,name:p.doctor.name,specialty:p.doctor.specialty||r.specialty,clinicName:p.clinic.name,phone:p.doctor.phone||p.clinic.phone||''};}db.mobileVisits.unshift(r);pushNotification(current.id,`🏠 تم إرسال طلب الزيارة المنزلية في ${r.specialty}.`,'mobile');save();requestBrowserNotifications();toast('تم إرسال طلب الزيارة 🏠');render();}
function cancelMobileVisitV7(id){const r=db.mobileVisits.find(x=>x.id===id);if(!r||r.userId!==current?.id)return;r.status='cancelled';pushNotification(current.id,'تم إلغاء طلب الزيارة المنزلية.','mobile');save();render();}

// Add home visit/emergency services to appointments and improve patient account.
const _renderAppointmentsV7=renderAppointments;
renderAppointments=function(){
  const box=document.getElementById('appointmentsBox');if(!box)return;
  if(!current)return _renderAppointmentsV7();
  if(current.type==='clinic')return renderClinicAppointments(box);
  const arr=db.appointments.filter(a=>a.userId===current.id).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));
  const visits=db.mobileVisits.filter(x=>x.userId===current.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  const emergencies=db.emergencies.filter(x=>x.userId===current.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  box.innerHTML=`<div class="section-head"><div><span class="eyebrow">مواعيدك وخدماتك</span><h2>📅 المواعيد</h2></div></div>${arr.map(a=>{let c=db.clinics.find(x=>x.id===a.clinicId);return `<div class="appointment"><div class="appointment-top"><b>${esc(c?.name||'عيادة')}</b><span class="status ${serviceStatusClass(a.status)}">${serviceStatusLabel(a.status)}</span></div><p>📅 ${a.date} · 🕐 ${a.time}</p><small>${esc(a.type||'استشارة')} ${a.note?'· '+esc(a.note):''}</small>${a.status==='pending'||a.status==='confirmed'?`<button class="btn btn-danger-soft" style="margin-top:8px" onclick="cancelAppointment('${a.id}')">إلغاء الموعد</button>`:''}${a.status==='completed'?`<button class="btn btn-soft" style="margin-top:8px" onclick="reviewAppointment('${a.id}')">⭐ تقييم</button>`:''}</div>`}).join('')||emptyCard('ما عندك حتى موعد عادي')}<h3 class="subsection-title">🏠 الزيارات المنزلية</h3>${visits.map(r=>`<div class="appointment service-list-card"><div class="appointment-top"><b>${esc(r.specialty)}</b><span class="status ${serviceStatusClass(r.status)}">${serviceStatusLabel(r.status)}</span></div><p>${esc(r.type)} ${r.date?`· ${r.date} ${r.time||''}`:'· الآن'}</p>${r.provider?`<small>👨‍⚕️ ${esc(r.provider.name)} · ${esc(r.provider.clinicName||'')}</small>`:''}</div>`).join('')||emptyCard('ما عندك حتى طلب زيارة منزلية')}<h3 class="subsection-title">🚨 الحالات المستعجلة</h3>${emergencies.slice(0,5).map(r=>`<div class="appointment service-list-card urgent-item"><div class="appointment-top"><b>${esc(r.type)}</b><span class="status ${serviceStatusClass(r.status)}">${serviceStatusLabel(r.status)}</span></div><p>${esc(r.severity||'حالة مستعجلة')} · ${new Date(r.createdAt).toLocaleString('ar-MA')}</p>${r.provider?`<small>👨‍⚕️ ${esc(r.provider.name)}</small>`:''}</div>`).join('')||emptyCard('ما عندك حتى طلب مستعجل')}`;
};

// Patient profile with personal details and notification permission.
const _renderProfileV7=renderProfile;
renderProfile=function(){const box=document.getElementById('profileBox');if(!current)return _renderProfileV7();if(current.type==='clinic')return renderClinicProfile(box);box.innerHTML=`<div class="profile-hero"><div class="profile-avatar">${esc((current.name||'م').slice(0,1))}</div><div><span class="eyebrow">حساب المريض</span><h2>${esc(current.name)} 👋</h2><small>${esc(current.phone||current.email||'')}</small></div></div><div class="profile-grid"><button class="profile-action" onclick="openPatientEditor()">👤 البيانات الشخصية <span>›</span></button><button class="profile-action" onclick="showScreen('appointments')">📅 مواعيدي وخدماتي <span>›</span></button><button class="profile-action" onclick="showScreen('favorites')">❤️ المفضلة <span>›</span></button><button class="profile-action" onclick="showScreen('notifications')">🔔 الإشعارات <span>›</span></button><button class="profile-action" onclick="requestBrowserNotifications()">🔔 تفعيل إشعارات الجهاز <span>›</span></button><button class="profile-action" onclick="openPasswordChange()">🔐 تغيير كلمة المرور <span>›</span></button><button class="profile-action danger-text" onclick="logout()">🚪 تسجيل الخروج</button></div>`}
function openPatientEditor(){openModal(`<h2>👤 بياناتي</h2><form class="form" onsubmit="savePatientEditor(event)"><label>الاسم الكامل<input id="ppName" required value="${esc(current.name||'')}"></label><label>الهاتف<input id="ppPhone" inputmode="tel" value="${esc(current.phone||'')}"></label><label>تاريخ الميلاد<input id="ppBirth" type="date" value="${esc(current.birthDate||'')}"></label><label>العنوان<textarea id="ppAddress">${esc(current.address||'')}</textarea></label><label>معلومات طبية اختيارية<textarea id="ppMedical">${esc(current.medicalInfo||'')}</textarea></label><button class="btn btn-primary">حفظ البيانات</button></form>`)}
function savePatientEditor(e){e.preventDefault();Object.assign(current,{name:ppName.value.trim(),phone:ppPhone.value.trim(),birthDate:ppBirth.value,address:ppAddress.value.trim(),medicalInfo:ppMedical.value.trim()});const u=db.users.find(x=>x.id===current.id);if(u)Object.assign(u,current);save();closeModal();render();toast('تم حفظ بياناتك')}

// Clinic details: doctors, home visits, contact and navigation.
const _openClinicV7=openClinic;
openClinic=function(id){
  _openClinicV7(id);
  setTimeout(()=>{
    const card=document.querySelector('#modalRoot .modal-card');if(!card||!selectedClinic)return;
    const actions=card.querySelector('.detail-actions');
    if(actions&&!card.querySelector('.home-visit-action')){
      const b=document.createElement('button');b.className='btn btn-home home-visit-action';b.textContent=selectedClinic.mobileVisit?'🏠 طلب زيارة منزلية':'🏠 الزيارات المنزلية غير متاحة';b.disabled=!selectedClinic.mobileVisit;b.onclick=()=>{closeModal();openMobileDoctorRequest()};actions.appendChild(b);
    }
    if(actions&&!card.querySelector('.call-clinic-action')&&selectedClinic.phone){const a=document.createElement('a');a.className='btn btn-outline call-clinic-action';a.href='tel:'+selectedClinic.phone;a.textContent='📞 اتصال بالعيادة';actions.appendChild(a)}
    if(actions&&!card.querySelector('.whatsapp-action')&&selectedClinic.phone){const a=document.createElement('a');a.className='btn btn-soft whatsapp-action';a.target='_blank';a.href='https://wa.me/'+String(selectedClinic.phone).replace(/\D/g,'');a.textContent='💬 WhatsApp';actions.appendChild(a)}
  },30);
};

// Clinic dashboard: show urgent/home-visit queues and provider availability.
const _renderClinicDashboardV7=renderClinicDashboard;
renderClinicDashboard=function(){
  _renderClinicDashboardV7();
  const c=db.clinics.find(x=>x.ownerId===current?.id);if(!c)return;
  const box=document.getElementById('clinicDashBox');if(!box)return;
  const urgent=db.emergencies.filter(r=>r.provider?.clinicId===c.id&&['searching','accepted','on_the_way','arrived'].includes(r.status));
  const visits=db.mobileVisits.filter(r=>r.provider?.clinicId===c.id&&['searching','accepted','on_the_way','arrived'].includes(r.status));
  const panel=document.createElement('div');panel.className='panel provider-queue';panel.innerHTML=`<h3>🚑 خدمات مباشرة</h3><div class="queue-kpis"><div><b>${urgent.length}</b><small>حالات مستعجلة</small></div><div><b>${visits.length}</b><small>زيارات منزلية</small></div></div>${urgent.map(r=>`<div class="queue-item urgent-item"><div><b>🚨 ${esc(r.type)} — ${esc(r.severity||'')}</b><small>${esc(r.address)}</small></div><div class="queue-actions"><button class="btn btn-primary" onclick="providerUpdateService('emergency','${r.id}','accepted')">قبول</button><button class="btn btn-soft" onclick="providerUpdateService('emergency','${r.id}','on_the_way')">في الطريق</button><button class="btn btn-soft" onclick="providerUpdateService('emergency','${r.id}','arrived')">وصل</button></div></div>`).join('')}${visits.map(r=>`<div class="queue-item"><div><b>🏠 ${esc(r.specialty)}</b><small>${esc(r.address)} · ${esc(r.type)}</small></div><div class="queue-actions"><button class="btn btn-primary" onclick="providerUpdateService('mobile','${r.id}','accepted')">قبول</button><button class="btn btn-soft" onclick="providerUpdateService('mobile','${r.id}','on_the_way')">في الطريق</button><button class="btn btn-soft" onclick="providerUpdateService('mobile','${r.id}','arrived')">وصل</button></div></div>`).join('')||emptyCard('لا توجد طلبات مباشرة موجهة لعيادتك')}</div>`;box.prepend(panel);
};
function providerUpdateService(kind,id,status){const arr=kind==='emergency'?db.emergencies:db.mobileVisits;const r=arr.find(x=>x.id===id);if(!r)return;r.status=status;if(status==='accepted'&&!r.provider){const c=db.clinics.find(x=>x.ownerId===current?.id),d=c?.doctors?.[0];if(c&&d)r.provider={clinicId:c.id,doctorId:d.id,name:d.name,specialty:d.specialty,clinicName:c.name,phone:d.phone||c.phone||''};}pushNotification(r.userId,`تحديث طلبك: ${serviceStatusLabel(status)}.` ,kind);save();renderClinicDashboard();toast('تم تحديث حالة الطلب')}

// Admin emergency/mobile controls: accept, assign and complete.
const _renderAdminV7=renderAdmin;
renderAdmin=function(){
  _renderAdminV7();
  const box=document.getElementById('adminBox');if(!box)return;
  const addQueue=(title,arr,kind)=>{if(!arr.length)return;const panel=document.createElement('div');panel.className='panel admin-service-panel';panel.innerHTML=`<h3>${title}</h3>${arr.slice(0,12).map(r=>`<div class="queue-item ${kind==='emergency'?'urgent-item':''}"><div><b>${esc(r.type||r.specialty||'طلب')}</b><small>📞 ${esc(r.phone||'')} · 📍 ${esc(r.address||'')} · ${new Date(r.createdAt).toLocaleString('ar-MA')}</small></div><div class="queue-actions"><span class="status ${serviceStatusClass(r.status)}">${serviceStatusLabel(r.status)}</span><button class="btn btn-soft" onclick="adminCompleteService('${kind}','${r.id}')">إتمام</button><button class="btn btn-danger-soft" onclick="adminCancelService('${kind}','${r.id}')">إلغاء</button></div></div>`).join('')}`;box.prepend(panel)};
  addQueue('🚨 آخر الحالات المستعجلة',db.emergencies.filter(r=>!['completed','cancelled'].includes(r.status)),'emergency');
  addQueue('🏠 آخر طلبات الزيارة المنزلية',db.mobileVisits.filter(r=>!['completed','cancelled'].includes(r.status)),'mobile');
};
function adminCompleteService(kind,id){const r=(kind==='emergency'?db.emergencies:db.mobileVisits).find(x=>x.id===id);if(!r)return;r.status='completed';pushNotification(r.userId,'تم إنهاء طلب الخدمة. نتمنى لك السلامة والعافية.','service');save();renderAdmin();}
function adminCancelService(kind,id){const r=(kind==='emergency'?db.emergencies:db.mobileVisits).find(x=>x.id===id);if(!r)return;r.status='cancelled';pushNotification(r.userId,'تم إلغاء طلب الخدمة من الإدارة.','service');save();renderAdmin();}

// Mobile schedule binding after screen render.
const _renderOriginalV7=render;
render=function(){_renderOriginalV7();if(screen==='mobileDoctor')bindMobileSchedule();};

// Broader medical specialty catalog for search and home-care requests.
['طب النوم','طب الألم','طب العناية المركزة','طب الكوارث','طب السموم','طب الأجنة','طب حديثي الولادة والعناية المركزة','جراحة الثدي','جراحة القولون والمستقيم','جراحة الكبد والمرارة والبنكرياس','جراحة السمنة والمناظير','جراحة التجميل والترميم','جراحة الوجه والفكين','جراحة اليد','جراحة القدم والكاحل','جراحة العمود الفقري','جراحة الأطفال والمسالك','أمراض الأوعية الدموية','أمراض المناعة الذاتية','أمراض العيون والشبكية','أمراض القرنية','أمراض الشبكية','أمراض السمع والتوازن','أمراض النطق واللغة','طب النطق والتخاطب','طب الأسنان الأطفال','طب اللثة','تركيبات الأسنان','طب الفم','الصحة النفسية','علم النفس السريري','العلاج الوظيفي','العلاج بالنطق','التمريض','القابلات','التغذية العلاجية','الصيدلة السريرية','التحاليل الطبية','علم الأحياء الطبية','علم الوراثة الطبية','الطب الوراثي','الطب الجزيئي','الطب التأهيلي','الطب التلطيفي'].forEach(s=>{if(!specialties.includes(s))specialties.push(s)});
setTimeout(()=>{try{render()}catch(_e){}},0);
